        [HttpPost("create-combo-order")]



        public async Task<IActionResult> CreateComboOrder([FromBody] CreateComboOrderRequest request)



        {



            if (request == null || string.IsNullOrWhiteSpace(request.OrderCode) || request.Items == null || request.Items.Count == 0)



            {



                return BadRequest(new { success = false, message = "Dữ liệu đơn hàng combo không hợp lệ." });



            }







            string cleanOrderCode = request.OrderCode.Trim().ToUpperInvariant();



            bool isCash = request.PaymentMethod.Contains("Tiền mặt", StringComparison.OrdinalIgnoreCase) ||



                          request.PaymentMethod.Contains("COD", StringComparison.OrdinalIgnoreCase);







            try



            {



                var orderDoc = new BsonDocument



                {



                    { "orderCode", cleanOrderCode },



                    { "userEmail", request.UserEmail ?? "buyer@zonemart.vn" },



                    { "customerName", request.CustomerName ?? "Khách Hàng ZoneMart" },



                    { "customerPhone", request.CustomerPhone ?? "0988888888" },



                    { "shippingAddress", request.ShippingAddress ?? "Vị trí người dùng" },



                    { "shippingMethod", request.ShippingMethod },



                    { "shippingFee", Convert.ToDouble(request.ShippingFee) },



                    { "paymentMethod", request.PaymentMethod },



                    { "isPaid", false },



                    { "paymentStatus", isCash ? "Pending" : "Unpaid" },



                    { "orderStatus", "Processing" },



                    { "totalAmount", Convert.ToDouble(request.GrandTotal) },



                    { "createdAt", DateTime.UtcNow },



                    { "orderType", "COMBO" },



                    { "comboName", request.ComboName ?? "Combo Đi Chợ Hộ" },



                    { "storesCount", request.StoresCount },



                    { "items", new BsonArray(request.Items.Select(it => new BsonDocument



                        {



                            { "productId", it.ProductId },



                            { "productName", it.ProductName },



                            { "price", Convert.ToDouble(it.Price) },



                            { "quantity", it.Quantity },



                            { "storeId", it.StoreId },



                            { "storeName", it.StoreName },



                            { "imageUrl", it.ImageUrl }



                        }))



                    }



                };







                await _mongoService.Database.GetCollection<BsonDocument>("Orders").InsertOneAsync(orderDoc);







                if (!isCash)



                {



                    _paidOrdersCache[cleanOrderCode] = false;



                    string digits = Regex.Replace(cleanOrderCode, @"[^\d]", "");



                    if (!string.IsNullOrEmpty(digits)) _paidOrdersCache[digits] = false;



                }







                return Ok(new { success = true, orderCode = cleanOrderCode });



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[CreateComboOrder Error] {ex.Message}");



                return StatusCode(500, new { success = false, message = "Lỗi khi lưu đơn hàng combo." });



            }



        }







        /// <summary>



        /// Quy trình 5 bước xác định vị trí và thời tiết hiện tại của khách hàng:



        /// BƯỚC 1: Lấy địa chỉ IP của Client từ HttpContext (Nếu 127.0.0.1 / ::1 -> gán IP thật 14.232.208.1 Hà Nội)



        /// BƯỚC 2: Gọi http://ip-api.com/json/{IP_của_khách} để trích xuất city



        /// BƯỚC 3: Truyền city vào OpenWeatherMap API: https://api.openweathermap.org/data/2.5/weather?q={city}&units=metric&lang=vi&appid=8cf6d64868efe0e4023e58c6fcd4d676



        /// BƯỚC 4: Trích xuất temp và description



        /// BƯỚC 5: Tạo chuỗi System Prompt: "Khách hàng đang ở {city}. Thời tiết hiện tại: {temp} độ C, {description}. Hãy gợi ý món ăn phù hợp với thời tiết này."



        /// </summary>



        private async Task<(string city, double temp, string description, string weatherPrompt)> GetClientWeatherInfoAsync()



        {



            // BƯỚC 1: Lấy địa chỉ IP của Client từ HttpContext



            string clientIp = string.Empty;



            try



            {



                if (Request.Headers.TryGetValue("X-Forwarded-For", out var forwardedFor) && !string.IsNullOrWhiteSpace(forwardedFor))



                {



                    clientIp = forwardedFor.ToString().Split(',')[0].Trim();



                }



                else if (Request.Headers.TryGetValue("X-Real-IP", out var realIp) && !string.IsNullOrWhiteSpace(realIp))



                {



                    clientIp = realIp.ToString().Trim();



                }







                if (string.IsNullOrWhiteSpace(clientIp))



                {



                    clientIp = HttpContext.Connection.RemoteIpAddress?.ToString() ?? "";



                }



            }



            catch { }







            // Lưu ý quan trọng: Nếu phát hiện IP là 127.0.0.1 hoặc ::1 do đang test local, tự động gán tạm một IP thật để test



            if (string.IsNullOrWhiteSpace(clientIp) ||



                clientIp == "127.0.0.1" ||



                clientIp == "::1" ||



                clientIp.StartsWith("127.") ||



                clientIp.StartsWith("::ffff:127.") ||



                clientIp.Equals("localhost", StringComparison.OrdinalIgnoreCase))



            {



                clientIp = "14.232.208.1"; // IP Hà Nội



            }







            // Kiểm tra cache thời tiết theo IP để tối ưu hiệu năng (trả về tức thì 0ms)



            lock (_weatherLock)



            {



                if (_cachedWeatherInfo != null &&



                    (_cachedWeatherInfo.Value.ip == clientIp || DateTime.UtcNow < _cachedWeatherInfo.Value.expireAt))



                {



                    return (_cachedWeatherInfo.Value.city, _cachedWeatherInfo.Value.temp, _cachedWeatherInfo.Value.description, _cachedWeatherInfo.Value.prompt);



                }



            }







            string city = "Hanoi";



            double temp = 28.5;



            string description = "mây rải rác, mát mẻ";







            try



            {



                // BƯỚC 2: Dùng HttpClient gọi API http://ip-api.com/json/{IP_của_khách}.



                using var ctsIp = new CancellationTokenSource(TimeSpan.FromMilliseconds(1200));



                var ipRes = await _httpClient.GetAsync($"http://ip-api.com/json/{clientIp}", ctsIp.Token);



                if (ipRes.IsSuccessStatusCode)



                {



                    string ipJson = await ipRes.Content.ReadAsStringAsync(ctsIp.Token);



                    using var ipDoc = JsonDocument.Parse(ipJson);



                    if (ipDoc.RootElement.TryGetProperty("city", out var cityProp) && !string.IsNullOrWhiteSpace(cityProp.GetString()))



                    {



                        city = cityProp.GetString()!;



                    }



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[Weather Service Warning] IP Lookup: {ex.Message}");



            }







            try



            {



                // BƯỚC 3: Dùng biến city vừa lấy được, truyền vào URL của OpenWeatherMap



                string weatherUrl = $"https://api.openweathermap.org/data/2.5/weather?q={Uri.EscapeDataString(city)}&units=metric&lang=vi&appid=8cf6d64868efe0e4023e58c6fcd4d676";



                using var ctsW = new CancellationTokenSource(TimeSpan.FromMilliseconds(1200));



                var weatherRes = await _httpClient.GetAsync(weatherUrl, ctsW.Token);



                if (weatherRes.IsSuccessStatusCode)



                {



                    string weatherJson = await weatherRes.Content.ReadAsStringAsync(ctsW.Token);



                    using var wDoc = JsonDocument.Parse(weatherJson);







                    // BƯỚC 4: Trích xuất temp và description từ kết quả thời tiết.



                    if (wDoc.RootElement.TryGetProperty("main", out var mainObj) && mainObj.TryGetProperty("temp", out var tempProp))



                    {



                        temp = Math.Round(tempProp.GetDouble(), 1);



                    }



                    if (wDoc.RootElement.TryGetProperty("weather", out var wArray) && wArray.ValueKind == JsonValueKind.Array && wArray.GetArrayLength() > 0)



                    {



                        var firstW = wArray[0];



                        if (firstW.TryGetProperty("description", out var descProp) && !string.IsNullOrWhiteSpace(descProp.GetString()))



                        {



                            description = descProp.GetString()!;



                        }



                    }



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[Weather Service Warning] OpenWeatherMap: {ex.Message}");



            }







            // BƯỚC 5: Bơm toàn bộ vào System Prompt của AI theo mẫu: "Khách hàng đang ở {city}. Thời tiết hiện tại: {temp} độ C, {description}. Hãy gợi ý món ăn phù hợp với thời tiết này."



            string weatherPrompt = $"Khách hàng đang ở {city}. Thời tiết hiện tại: {temp:0.#} độ C, {description}. Hãy gợi ý món ăn phù hợp với thời tiết này.";







            lock (_weatherLock)



            {



                _cachedWeatherInfo = (clientIp, city, temp, description, weatherPrompt, DateTime.UtcNow.AddMinutes(30));



            }







            return (city, temp, description, weatherPrompt);



        }







        private async Task<List<Store>> GetCachedActiveStoresAsync()



        {



            lock (_storesLock)



            {



                if (_cachedStores != null && DateTime.UtcNow < _cachedStores.Value.expireAt && _cachedStores.Value.stores.Count > 0)



                {



                    return _cachedStores.Value.stores;



                }



            }







            try



            {



                using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(2));



                var stores = await _mongoService.Stores



                    .Find(s => s.Status != "Rejected" && s.Status != "deleted")



                    .ToListAsync(cts.Token);







                if (stores != null && stores.Count > 0)



                {



                    lock (_storesLock)



                    {



                        _cachedStores = (stores, DateTime.UtcNow.AddSeconds(120));



                    }



                    return stores;



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"⚠️ [GetCachedActiveStoresAsync Warning] {ex.Message}. Using fallback stores.");



            }







            var fallbackStores = new List<Store>



            {



                new Store { Id = "65f01234567890abcdef0001", StoreName = "ZoneMart Bách Hóa Cầu Giấy", Address = "12 Xuân Phương, Nam Từ Liêm, Hà Nội", Category = "Thực phẩm tươi sạch" },



                new Store { Id = "65f01234567890abcdef0002", StoreName = "Tiệm Bánh Mì Zone & Nước Ép", Address = "45 Trần Duy Hưng, Cầu Giấy, Hà Nội", Category = "Đồ ăn nhanh & Nước ép" }



            };







            lock (_storesLock)



            {



                _cachedStores = (fallbackStores, DateTime.UtcNow.AddSeconds(120));



            }



            return fallbackStores;



        }







        private async Task<List<Product>> GetCachedActiveProductsAsync()



        {



            lock (_productsLock)



            {



                if (_cachedProducts != null && DateTime.UtcNow < _cachedProducts.Value.expireAt && _cachedProducts.Value.products.Count > 0)



                {



                    return _cachedProducts.Value.products;



                }



            }







            try



            {



                using var cts = new CancellationTokenSource(TimeSpan.FromSeconds(2.5));



                var prods = await _mongoService.Products



                    .Find(p => p.StockStatus != "out_of_stock" && p.AiStatus == "approved")



                    .ToListAsync(cts.Token);







                if (prods != null && prods.Count > 0)



                {



                    try



                    {



                        var stores = await GetCachedActiveStoresAsync();



                        if (stores != null && stores.Count > 0)



                        {



                            var storeMap = stores.ToDictionary(s => s.Id ?? "", s => s.StoreName ?? "ZoneMart Store");



                            foreach (var p in prods)



                            {



                                if (!string.IsNullOrWhiteSpace(p.StoreId) && storeMap.TryGetValue(p.StoreId, out var sName) && !string.IsNullOrWhiteSpace(sName))



                                {



                                    p.StoreName = sName;



                                }



                            }



                        }



                    }



                    catch { }







                    lock (_productsLock)



                    {



                        _cachedProducts = (prods, DateTime.UtcNow.AddSeconds(120));



                    }



                    return prods;



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"⚠️ [GetCachedActiveProductsAsync Warning] {ex.Message}. Using fallback catalog.");



            }







            var fallbackProds = GetFallbackProductCatalog();



            lock (_productsLock)



            {



                _cachedProducts = (fallbackProds, DateTime.UtcNow.AddSeconds(120));



            }



            return fallbackProds;



        }







