        [HttpPost("safe-location")]



        public async Task<IActionResult> GetSafeLocation([FromBody] SafeLocationRequest request)



        {



            if (request == null)



            {



                return BadRequest(new { success = false, message = "Tọa độ GPS không hợp lệ." });



            }



            double effectiveLat = request.Lat;



            double effectiveLon = request.Lon != 0 ? request.Lon : request.Lng;



            if (effectiveLat == 0 && effectiveLon == 0)



            {



                return BadRequest(new { success = false, message = "Tọa độ GPS không hợp lệ." });



            }



            // Phòng ngừa kinh độ = 0 hoặc ngoài lãnh thổ Việt Nam gây lỗi dịch sai sang Châu Phi/Mali



            if (effectiveLon == 0 || effectiveLon < 100 || effectiveLon > 115 || effectiveLat < 8 || effectiveLat > 24)



            {



                Console.WriteLine($"[GPS Backend]: Cảnh báo tọa độ bất thường ngoài VN: Lat={effectiveLat}, Lon={effectiveLon}. Dùng mặc định Hà Nội.");



                effectiveLat = 21.0333;



                effectiveLon = 105.7983;



            }



            // Tọa độ GPS thật sự CHỈ hiện ở Backend Console, TUYỆT ĐỐI không trả tọa độ số về Frontend



            Console.WriteLine($"[GPS Backend]: Nhận tọa độ GPS thực tế từ Client: Lat={effectiveLat}, Lon={effectiveLon}");



            var (safeLocationName, amenity, hamlet, suburb, district, city) = await ResolveSafeLocationFromGpsAsync(effectiveLat, effectiveLon);







            Console.WriteLine($"[GPS Backend]: Đã dịch thành địa danh an toàn cho AI Tư Vấn: {safeLocationName}");







            return Ok(new



            {



                success = true,



                safeLocationName,



                amenity,



                hamlet,



                suburb,



                district,



                city



            });



        }







        private static string SanitizeStreetOrAlley(string? name)



        {



            if (string.IsNullOrWhiteSpace(name)) return "";



            string cleaned = name.Trim();







            // Nếu tên là cơ sở/trường học/bệnh viện/công ty/học viện thì KHÔNG coi là tên đường/ngõ



            if (Regex.IsMatch(cleaned, @"\b(trường|truong|cao đẳng|cao dang|đại học|dai hoc|học viện|hoc vien|ủy ban|uy ban|bệnh viện|benh vien|công an|cong an|doanh nghiệp|công ty)\b", RegexOptions.IgnoreCase))



            {



                return "";



            }







            // Loại bỏ tiền tố số nhà cụ thể: "Số 12 ", "Số 12A/3 ", "12 ", "15/3B ", "Số 25, "...



            cleaned = Regex.Replace(cleaned, @"^(số\s*)?\d+[a-zA-Z]?(\s*[-/]\s*\d+[a-zA-Z]?)*\s*(,\s*|\s+)", "", RegexOptions.IgnoreCase).Trim();







            // Nếu chuỗi chỉ toàn là số nhà đơn thuần thì loại bỏ hoàn toàn



            if (Regex.IsMatch(cleaned, @"^(số\s*)?\d+[a-zA-Z]?(\s*[-/]\s*\d+[a-zA-Z]?)*$", RegexOptions.IgnoreCase))



            {



                return "";



            }



            return cleaned;



        }







