            // 0.005. TÍNH NĂNG TRUY XUẤT CỬA HÀNG MỞ CỬA THEO KHUNG GIỜ NGƯỜI DÙNG YÊU CẦU (18h, 18 giờ, tầm 17h có quán nào mở, tầm 16h có ai bán sản phẩm...)



            bool isRegActive = !string.IsNullOrWhiteSpace(request?.RegistrationState) &&



                               !string.Equals(request.RegistrationState, "NONE", StringComparison.OrdinalIgnoreCase);







            if (!isRegActive && TryParseStoreHoursQuery(userMsg, cleanMsgNoTone, out TimeSpan targetStoreHour, out string storeHourDisplay))



            {



                var allActiveStores = await GetCachedActiveStoresAsync();



                var openStoresAtTime = allActiveStores.Where(s => IsStoreOpenAtTime(s.OpenHours, targetStoreHour)).ToList();







                var storeIds = openStoresAtTime.Select(s => s.Id).Where(id => !string.IsNullOrEmpty(id)).ToList();



                var storeNames = openStoresAtTime.Select(s => s.StoreName).Where(n => !string.IsNullOrEmpty(n)).ToList();



                var allProds = await GetCachedActiveProductsAsync();



                var storeProducts = allProds



                    .Where(p => (p.StoreId != null && storeIds.Contains(p.StoreId)) || (p.StoreName != null && storeNames.Contains(p.StoreName)))



                    .ToList();







