                    int idx = 1;



                    foreach (var s in openStoresAtTime)



                    {



                        string addr = string.IsNullOrWhiteSpace(s.Address) ? "Khu vực Cầu Giấy, Hà Nội" : s.Address;



                        string cat = string.IsNullOrWhiteSpace(s.Category) ? "Thực phẩm & Nhu yếu phẩm" : s.Category;



                        string hours = string.IsNullOrWhiteSpace(s.OpenHours) ? "07:00 - 22:00" : s.OpenHours;







                        sbHours.AppendLine($"{idx}️⃣ **{s.StoreName}** 🟢 *(Đang mở cửa đón khách)*");



                        sbHours.AppendLine($"   📍 Địa chỉ: {addr}");



                        sbHours.AppendLine($"   🏷️ Chuyên bán: {cat} | ⏰ Khung giờ hoạt động: {hours}");







