                        if (prods.Count > 0)



                        {



                            var pList = string.Join(", ", prods.Select(p => $"{p.ProductName} ({p.Price:N0}đ)"));



                            sbHours.AppendLine($"   🍲 Món nổi bật: {pList}");



                        }



                        sbHours.AppendLine();



                        idx++;



                    }







                    sbHours.AppendLine("Bạn muốn đặt món gì tại quán nào thì cứ nhắn tên món hoặc số lượng (ví dụ: *'lấy tôi 2 cái bánh mỳ chảo'*) để mình tạo đơn giao ngay tận cửa cho bạn nhé! 🚀✨");



                }



                else



                {



                    sbHours.AppendLine($"Dạ vào khung giờ **{storeHourDisplay}**, hiện tại các cửa hàng trên hệ thống sàn ZoneMart đều đã đóng cửa để nghỉ ngơi (khung giờ hoạt động mở bán phổ biến là từ **06:00 đến 23:00** hàng ngày) ạ. 🌙✨");



                    sbHours.AppendLine();



                    sbHours.AppendLine("Bạn vui lòng quay lại vào ban ngày để được các gian hàng phục vụ món ngon & nông sản hỏa tốc 15 - 30 phút nhé! 😊");



                }







                var timeStoreCards = openStoresAtTime.Take(6).Select(s => (object)new



