                    rating = "4.9"



                }).ToList();







                var timeProdCards = storeProducts.Take(4).Select(p => (object)new



                {



                    id = p.Id,



                    name = p.ProductName,



                    price = p.Price,



                    image = !string.IsNullOrEmpty(p.ImageUrl) ? p.ImageUrl : "/images/anhxoanen.png",



                    storeName = p.StoreName ?? "ZoneMart Store",



                    category = p.Category



                }).ToList();







                return Ok(new



                {



                    success = true,



                    reply = sbHours.ToString().TrimEnd(),



                    provider = "ZoneMart Store Schedule AI",



                    orderState = request?.OrderState ?? new OrderStateDto { Step = "IDLE" },



                    stores = timeStoreCards,



                    products = timeProdCards,



                    actionIntent = (string?)null



                });



            }







            // 0.01. NẾU ĐANG TRONG TIẾN TRÌNH ĐĂNG KÝ HỘ HOẶC CÓ Ý ĐỊNH ĐĂNG KÝ HỘ (SELLER / SHIPPER / BUYER) -> ƯU TIÊN XỬ LÝ TRƯỚC



            bool isStoreOrHourInquiry = cleanMsgNoTone.Contains("co ai ban") ||



                                         cleanMsgNoTone.Contains("co ban khong") ||



                                         cleanMsgNoTone.Contains("ban hang khong") ||



                                         cleanMsgNoTone.Contains("quan nao") ||



                                         cleanMsgNoTone.Contains("tiem nao") ||



                                         cleanMsgNoTone.Contains("co mo") ||



                                         cleanMsgNoTone.Contains("mo cua") ||



                                         cleanMsgNoTone.Contains("mo ban") ||



                                         cleanMsgNoTone.Contains("co khong") ||



                                         Regex.IsMatch(cleanMsgNoTone, @"\b\d{1,2}\s*(?:h|gio|g|:)\b");







            bool isRegIntent = !isStoreOrHourInquiry && (



                               cleanMsgNoTone.Contains("ai dang ky") ||



                               cleanMsgNoTone.Contains("dang ky ho") ||



                               cleanMsgNoTone.Contains("dang ky giup") ||



                               cleanMsgNoTone.Contains("dang ky bang ai") ||



                               cleanMsgNoTone.Contains("dang ky truc tiep") ||



                               cleanMsgNoTone.Contains("nhap thong tin") ||



                               cleanMsgNoTone.Contains("nho ai dang ky") ||



