                               cleanMsgNoTone.Contains("toi muon ai dang ky") ||



                               cleanMsgNoTone.Contains("cach 2") ||



                               cleanMsgNoTone.Contains("dang ky") ||



                               cleanMsgNoTone.Contains("dangky") ||



                               cleanMsgNoTone.Contains("tao tai khoan") ||



                               cleanMsgNoTone.Contains("lap tai khoan") ||



                               ((cleanMsgNoTone.Contains("shipper") || cleanMsgNoTone.Contains("tai xe") || cleanMsgNoTone.Contains("chay xe")) &&



                                (cleanMsgNoTone.Contains("dang ky") || cleanMsgNoTone.Contains("lam") || cleanMsgNoTone.Contains("chay") || cleanMsgNoTone.Contains("muon"))) ||



                               (cleanMsgNoTone.Contains("dang ky seller") || cleanMsgNoTone.Contains("dang ky ban hang") || cleanMsgNoTone.Contains("dang ky gian hang") || cleanMsgNoTone.Contains("dang ky shop") || cleanMsgNoTone.Contains("mo gian hang") || cleanMsgNoTone.Contains("mo shop") || cleanMsgNoTone.Contains("toi muon ban hang") || cleanMsgNoTone.Contains("muon mo gian hang") || cleanMsgNoTone.Contains("muon mo shop") || cleanMsgNoTone.Contains("muon lam seller") || cleanMsgNoTone.Contains("muon ban hang")) ||



                               ((cleanMsgNoTone.Contains("khach hang") || cleanMsgNoTone.Contains("nguoi mua") || cleanMsgNoTone.Contains("tai khoan")) &&



                                (cleanMsgNoTone.Contains("dang ky") || cleanMsgNoTone.Contains("tao") || cleanMsgNoTone.Contains("lap") || cleanMsgNoTone.Contains("muon"))) ||

                               cleanMsgNoTone.Contains("nang cap") || cleanMsgNoTone.Contains("len seller") || cleanMsgNoTone.Contains("len shipper"));







            if (isRegActive || isRegIntent)



