                                {



                                    inCartItem = it;



                                    break;



                                }



                            }







                            if (inCartItem != null)



                            {



                                // ĐÃ CÓ TRONG GIỎ HÀNG: CỘNG DỒN SỐ LƯỢNG



                                inCartItem.Quantity += q;



                                recordedChanges.Add($"➕ Tăng món **{inCartItem.ProductName}** thêm +{q} (hiện có: **{inCartItem.Quantity}**)");



                            }



                            else



