                    var traProd = drinkAndDesserts.FirstOrDefault(p => p.ProductName.Contains("Trà Tắc"));

                    if (traProd != null) returnProducts.Add(traProd);

                    var duaProd = drinkAndDesserts.FirstOrDefault(p => p.ProductName.Contains("Dừa"));

