        private static CategoryBrowseDefinition? MatchCategoryDefinition(string cleanMsgNoTone)
        {
            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return null;

            // 1. Phân loại 1: Thực phẩm tươi (food)
            if (cleanMsgNoTone.Contains("thuc pham tuoi") || cleanMsgNoTone.Contains("do an tuoi") ||
                cleanMsgNoTone.Contains("do tuoi") || cleanMsgNoTone.Contains("thit ca") ||
                cleanMsgNoTone.Contains("thit tuoi") || cleanMsgNoTone.Contains("hai san tuoi") ||
                cleanMsgNoTone.Contains("thuc pham") || cleanMsgNoTone == "tuoi" || cleanMsgNoTone == "do song" ||
                cleanMsgNoTone.Contains("thit bo") || cleanMsgNoTone.Contains("thit heo") || cleanMsgNoTone.Contains("thit ga"))
            {
                return _categoryDefinitions.First(d => d.Id == "food");
            }

            // 2. Phân loại 2: Rau củ VietGAP (veggie)
            if (cleanMsgNoTone.Contains("rau cu") || cleanMsgNoTone.Contains("rau xanh") ||
                cleanMsgNoTone.Contains("vietgap") || cleanMsgNoTone.Contains("nong san") ||
                cleanMsgNoTone.Contains("cu qua") || cleanMsgNoTone.Contains("rau an la") ||
                cleanMsgNoTone == "rau" || cleanMsgNoTone.Contains("rau sach") || cleanMsgNoTone.Contains("rau huu co"))
            {
                return _categoryDefinitions.First(d => d.Id == "veggie");
            }

            // 3. Phân loại 3: Món ăn nóng (fastfood)
            if (cleanMsgNoTone.Contains("mon an nong") || cleanMsgNoTone.Contains("do an nong") ||
                cleanMsgNoTone.Contains("mon nong") || cleanMsgNoTone.Contains("do nong") ||
                cleanMsgNoTone.Contains("fast food") || cleanMsgNoTone.Contains("fastfood") ||
                cleanMsgNoTone.Contains("thuc an nhanh") || cleanMsgNoTone.Contains("do an nhanh") ||
                cleanMsgNoTone.Contains("ga ran") || cleanMsgNoTone.Contains("do an chin"))
            {
                return _categoryDefinitions.First(d => d.Id == "fastfood");
            }

            // 4. Phân loại 4: Đồ uống & Trái cây (beverage)
            if (cleanMsgNoTone.Contains("do uong") || cleanMsgNoTone.Contains("thuc uong") ||
                cleanMsgNoTone.Contains("trai cay") || cleanMsgNoTone.Contains("hoa qua") ||
                cleanMsgNoTone.Contains("nuoc uong") || cleanMsgNoTone.Contains("sinh to") ||
                cleanMsgNoTone.Contains("nuoc ep") || cleanMsgNoTone.Contains("ca phe") ||
                cleanMsgNoTone.Contains("tra sua") || cleanMsgNoTone == "uong" || cleanMsgNoTone == "nuoc")
            {
                return _categoryDefinitions.First(d => d.Id == "beverage");
            }

            // 5. Phân loại 5: Nhu yếu phẩm (household)
            if (cleanMsgNoTone.Contains("nhu yeu pham") || cleanMsgNoTone.Contains("gia dung") ||
                cleanMsgNoTone.Contains("do gia dung") || cleanMsgNoTone.Contains("bep nuc") ||
                cleanMsgNoTone.Contains("gia vi") || cleanMsgNoTone.Contains("do dung"))
            {
                return _categoryDefinitions.First(d => d.Id == "household");
            }

            // Fallback trigger keywords
            foreach (var def in _categoryDefinitions)
            {
                foreach (var kw in def.TriggerKeywords)
                {
                    if (cleanMsgNoTone.Contains(kw))
                    {
                        return def;
                    }
                }
            }

            return null;
        }

        private static bool IsCategoryBrowseIntent(string cleanMsgNoTone, string rawMsg = "")
        {
            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;

            // Loại trừ nếu là đặt hàng có số lượng cụ thể (vd: "đặt 2 món", "mua 3 cốc", "cho 1 phở")
            if (Regex.IsMatch(cleanMsgNoTone, @"\b(dat|mua|cho|lay|them)\s+\d+\b")) return false;

            // Hỏi danh mục / phân loại trực tiếp
            if (cleanMsgNoTone.Contains("phan loai") ||
                cleanMsgNoTone.Contains("danh muc") ||
                cleanMsgNoTone.Contains("nhom hang") ||
                cleanMsgNoTone.Contains("nganh hang"))
            {
                return true;
            }

            // Người dùng có từ khóa muốn xem / tham khảo
            bool hasBrowseVerb = cleanMsgNoTone.Contains("xem") ||
                                 cleanMsgNoTone.Contains("cho xem") ||
                                 cleanMsgNoTone.Contains("tim") ||
                                 cleanMsgNoTone.Contains("goi y") ||
                                 cleanMsgNoTone.Contains("tham khao") ||
                                 cleanMsgNoTone.Contains("co nhung") ||
                                 cleanMsgNoTone.Contains("danh sach") ||
                                 cleanMsgNoTone.Contains("muon xem") ||
                                 cleanMsgNoTone.Contains("toi muon") ||
                                 cleanMsgNoTone.Contains("muon") ||
                                 cleanMsgNoTone.StartsWith("cho toi xem");

            var matchedCat = MatchCategoryDefinition(cleanMsgNoTone);
            if (matchedCat != null)
            {
                // Nếu có hành động xem/tìm/gợi ý HOẶC là câu ngắn (dưới 5 từ nói về phân loại)
                if (hasBrowseVerb || cleanMsgNoTone.Split(' ', StringSplitOptions.RemoveEmptyEntries).Length <= 4)
                {
                    return true;
                }
            }

            return false;
        }


        private static bool IsGeneralCategoryOverviewQuery(string cleanMsgNoTone)
        {
            return cleanMsgNoTone.Contains("goi y phan loai") ||
                   cleanMsgNoTone.Contains("phan loai do trong web") ||
                   cleanMsgNoTone.Contains("phan loai hang") ||
                   cleanMsgNoTone.Contains("cac phan loai") ||
                   cleanMsgNoTone.Contains("danh muc san pham") ||
                   cleanMsgNoTone.Contains("danh muc nganh hang") ||
                   cleanMsgNoTone.Contains("co nhung phan loai nao") ||
                   cleanMsgNoTone.Contains("co bao nhieu phan loai") ||
                   (cleanMsgNoTone.Contains("phan loai") && !cleanMsgNoTone.Contains("tuoi") && !cleanMsgNoTone.Contains("rau") && !cleanMsgNoTone.Contains("uong") && !cleanMsgNoTone.Contains("nong") && !cleanMsgNoTone.Contains("gia dung"));
        }

        private static string InferProductPrepType(Product p)
        {
            string name = (p.ProductName ?? "").ToLower();
            string cat = (p.Category ?? "").ToLower();

            if (name.Contains("gà rán") || name.Contains("kfc") || name.Contains("chiên giòn") ||
                name.Contains("cơm") || name.Contains("bún") || name.Contains("phở") || name.Contains("mì") ||
                name.Contains("bánh mì") || name.Contains("bánh bao") || name.Contains("xôi") ||
                name.Contains("cà phê") || name.Contains("cafe") || name.Contains("trà ") || name.Contains("nóng") ||
                name.Contains("chín") || name.Contains("luộc") || name.Contains("nướng") || name.Contains("kho"))
            {
                return "cooked";
            }

            if (name.Contains("thịt") || name.Contains("bò") || name.Contains("heo") || name.Contains("lợn") ||
                name.Contains("gà") || name.Contains("vịt") || name.Contains("cá ") || name.Contains("tôm") ||
                name.Contains("mực") || name.Contains("hải sản") || name.Contains("trứng") || name.Contains("đậu phụ") ||
                name.Contains("sống") || name.Contains("sơ chế"))
            {
                return "raw";
            }

            if (name.Contains("rau") || name.Contains("xà lách") || name.Contains("cải") || name.Contains("cà chua") ||
                name.Contains("dâu") || name.Contains("bơ") || name.Contains("cam") || name.Contains("trái cây") ||
                name.Contains("hoa quả") || name.Contains("nước ép") || name.Contains("sinh tố") || name.Contains("dừa") ||
                name.Contains("bí") || name.Contains("nấm") || name.Contains("khoai"))
            {
                return "fresh";
            }

            if (name.Contains("nồi") || name.Contains("chảo") || name.Contains("nước giặt") || name.Contains("nước rửa") ||
                name.Contains("lau") || name.Contains("muối") || name.Contains("đường") || name.Contains("mắm") ||
                name.Contains("gia vị") || name.Contains("mật ong") || name.Contains("gạo"))
            {
                return "packaged";
            }

            if (cat.Contains("món ăn") || cat.Contains("nóng")) return "cooked";
            if (cat.Contains("thực phẩm tươi")) return "raw";
            if (cat.Contains("rau củ") || cat.Contains("trái cây")) return "fresh";
            return "fresh";
        }

        private static List<Product> FilterApprovedProductsByCategory(List<Product> allDbProds, string catId, string subCatId, string dishStatusId = "all")
        {
            var approved = allDbProds.Where(p => p.AiStatus == "approved" && p.StockStatus != "out_of_stock").ToList();
            var list = approved;

            if (catId == "food")
            {
                var baseList = approved.Where(p => p.Category.Contains("Thực phẩm") || p.Category.Contains("thịt") || p.Category.Contains("hải sản") || p.Category.Contains("trứng")).ToList();
                if (subCatId == "poultry") baseList = baseList.Where(p => Regex.IsMatch(p.ProductName, @"\b(gà|vit|canh ga|dui ga|uc ga)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "beef_pork") baseList = baseList.Where(p => Regex.IsMatch(p.ProductName, @"\b(bò|heo|lợn|ba chỉ|sườn|trau)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "seafood") baseList = baseList.Where(p => Regex.IsMatch(p.ProductName, @"\b(cá|tôm|mực|hải sản|cua|hàu)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "egg_tofu") baseList = baseList.Where(p => Regex.IsMatch(p.ProductName, @"\b(trứng|đậu phụ|đậu hũ)\b", RegexOptions.IgnoreCase)).ToList();
                list = baseList.Count > 0 ? baseList : approved.Where(p => p.Category.Contains("Thực phẩm")).ToList();
            }
            else if (catId == "veggie")
            {
                var vegBase = approved.Where(p => p.Category.Contains("Rau củ") || p.Category.Contains("nông sản")).ToList();
                if (subCatId == "leafy") vegBase = vegBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(xà lách|rau muống|cải|mồng tơi|rau)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "root_fruit") vegBase = vegBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(cà chua|bí|khoai|cà rốt|bầu|ớt chuông|dưa chuột)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "mushroom_spices") vegBase = vegBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(nấm|hành|tỏi|ớt|gừng|gia vị)\b", RegexOptions.IgnoreCase)).ToList();
                list = vegBase.Count > 0 ? vegBase : approved.Where(p => p.Category.Contains("Rau củ")).ToList();
            }
            else if (catId == "fastfood")
            {
                var fastBase = approved.Where(p => p.Category.Contains("Món ăn") || p.Category.Contains("nóng") || p.Category.Contains("cơm") || p.Category.Contains("bánh mì")).ToList();
                if (subCatId == "fried_chicken") fastBase = fastBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(gà rán|kfc|popcorn|chiên giòn)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "rice_noodle") fastBase = fastBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(cơm|mì|phở|bún|cháo|canh)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "breakfast_bread") fastBase = fastBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(bánh mì|ăn sáng|bánh bao|xôi)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "snack") fastBase = fastBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(ăn vặt|snack|nem chua|xúc xích)\b", RegexOptions.IgnoreCase)).ToList();
                list = fastBase.Count > 0 ? fastBase : approved.Where(p => p.Category.Contains("Món ăn")).ToList();
            }
            else if (catId == "beverage")
            {
                var bevBase = approved.Where(p => p.Category.Contains("Đồ uống") || p.Category.Contains("Trái cây") || Regex.IsMatch(p.ProductName, @"\b(trà|cà phê|nước|sinh tố|dâu|bơ|cam|bưởi|xoài|dừa)\b", RegexOptions.IgnoreCase)).ToList();
                if (subCatId == "fruit") bevBase = bevBase.Where(p => p.Category.Contains("Trái cây") || Regex.IsMatch(p.ProductName, @"\b(dâu|bơ|cam|bưởi|xoài|hoa quả|trái cây)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "tea_coffee") bevBase = bevBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(trà|cà phê|cafe)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "juice_smoothie") bevBase = bevBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(nước cam|nước ép|dừa|sinh tố)\b", RegexOptions.IgnoreCase)).ToList();
                list = bevBase.Count > 0 ? bevBase : approved.Where(p => p.Category.Contains("Đồ uống") || p.Category.Contains("Trái cây")).ToList();
            }
            else if (catId == "household")
            {
                var houseBase = approved.Where(p => p.Category.Contains("gia dụng") || p.Category.Contains("gia đình") || p.Category.Contains("tiêu dùng")).ToList();
                if (subCatId == "kitchen") houseBase = houseBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(nồi|chảo|mật ong|gia vị|muối|đường|mắm)\b", RegexOptions.IgnoreCase)).ToList();
                else if (subCatId == "cleaning") houseBase = houseBase.Where(p => Regex.IsMatch(p.ProductName, @"\b(nước rửa|nước giặt|lau nhà|tẩy)\b", RegexOptions.IgnoreCase)).ToList();
                list = houseBase.Count > 0 ? houseBase : approved.Where(p => p.Category.Contains("gia dụng")).ToList();
            }

            // Lọc tiếp theo trạng thái món (Prep Type Filter: raw, cooked, fresh, packaged)
            if (!string.IsNullOrEmpty(dishStatusId) && dishStatusId != "all")
            {
                var prepFiltered = list.Where(p => InferProductPrepType(p) == dishStatusId).ToList();
                if (prepFiltered.Count > 0)
                {
                    list = prepFiltered;
                }
            }

            return list;
        }

        private async Task<IActionResult?> TryHandleCategoryBrowseFlowAsync(string userMsg, string cleanMsgNoTone, ChatRequest? request)
        {
            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return null;

            // KIỂM TRA LỆNH HỦY LUỒNG
            bool isCancelCmd = cleanMsgNoTone == "huy" || cleanMsgNoTone == "huy luong" ||
                               cleanMsgNoTone == "dung" || cleanMsgNoTone == "thoi" ||
                               cleanMsgNoTone == "thoat" || cleanMsgNoTone == "khong xem nua" ||
                               cleanMsgNoTone == "huy goi y" || cleanMsgNoTone.StartsWith("huy ");

            var currentCategoryState = request?.CategoryState ?? new CategoryBrowseStateDto();
            string activeStep = (currentCategoryState.Step ?? "NONE").ToUpperInvariant();

            // =========================================================================
            // GIAI ĐOẠN 1: NGƯỜI DÙNG ĐANG TRONG TRẠNG THÁI CHỜ CHỌN TRẠNG THÁI MÓN (AWAITING_DISH_STATUS)
            // =========================================================================
            if (activeStep == "AWAITING_DISH_STATUS")
            {
                if (isCancelCmd)
                {
                    return Ok(new
                    {
                        success = true,
                        reply = "Dạ mình đã hủy luồng gợi ý phân loại sản phẩm rồi nhé! Bây giờ bạn có thể trò chuyện hoặc hỏi mình các thông tin khác bất cứ lúc nào ạ!",
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto { Step = "NONE" },
                        actionIntent = (string?)null
                    });
                }

                string currentCatId = !string.IsNullOrWhiteSpace(currentCategoryState.CategoryId)
                    ? currentCategoryState.CategoryId
                    : "beverage";

                var catDef = _categoryDefinitions.FirstOrDefault(d => d.Id == currentCatId)
                             ?? _categoryDefinitions.First(d => d.Id == "beverage");

                var availableStatuses = catDef.DishStatuses.Count > 0
                    ? catDef.DishStatuses
                    : new List<CategoryBrowseOption> { new CategoryBrowseOption { Id = "all", Name = "Tất cả trạng thái", Icon = "<i class=\"bi bi-layers-fill\"></i>" } };

                // Khớp trạng thái món theo số thứ tự 1, 2, 3... hoặc từ khóa
                CategoryBrowseOption? matchedStatus = null;
                var numMatch = Regex.Match(cleanMsgNoTone, @"\b([1-9])\b");
                if (numMatch.Success && int.TryParse(numMatch.Groups[1].Value, out int selectedIdx))
                {
                    if (selectedIdx >= 1 && selectedIdx <= availableStatuses.Count)
                    {
                        matchedStatus = availableStatuses[selectedIdx - 1];
                    }
                }

                if (matchedStatus == null)
                {
                    foreach (var ds in availableStatuses)
                    {
                        string dsClean = RemoveVietnameseTones(ds.Name).ToLower();
                        if (cleanMsgNoTone.Contains(dsClean) || dsClean.Contains(cleanMsgNoTone))
                        {
                            matchedStatus = ds;
                            break;
                        }
                        foreach (var kw in ds.MatchKeywords)
                        {
                            if (cleanMsgNoTone.Contains(kw))
                            {
                                matchedStatus = ds;
                                break;
                            }
                        }
                        if (matchedStatus != null) break;
                    }
                }

                // NẾU NHẬP SAI: BẮT BUỘC HỎI LẠI TRẠNG THÁI MÓN
                if (matchedStatus == null)
                {
                    var sbStatusErr = new StringBuilder();
                    sbStatusErr.AppendLine($"<i class=\"bi bi-exclamation-triangle-fill text-warning me-1\"></i> Dạ lựa chọn trạng thái món của bạn chưa chính xác rồi ạ!");
                    sbStatusErr.AppendLine();
                    sbStatusErr.AppendLine($"Hiện tại nhóm hàng **{currentCategoryState.SubCategoryName}** ({catDef.Name}) gồm các trạng thái món sau:");
                    for (int i = 0; i < availableStatuses.Count; i++)
                    {
                        sbStatusErr.AppendLine($"{i + 1}. {availableStatuses[i].Icon} **{availableStatuses[i].Name}**");
                    }
                    sbStatusErr.AppendLine();
                    sbStatusErr.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn trạng thái món nào ạ?**");
                    sbStatusErr.AppendLine("*(Bạn vui lòng chọn đúng **số thứ tự (1, 2, 3...)** hoặc gõ đúng **tên trạng thái món** ở trên nhé! Nhắn **'hủy'** để dừng luồng gợi ý đồ ạ)*");

                    return Ok(new
                    {
                        success = true,
                        reply = sbStatusErr.ToString(),
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto
                        {
                            Step = "AWAITING_DISH_STATUS",
                            CategoryId = catDef.Id,
                            CategoryName = catDef.Name,
                            SubCategoryId = currentCategoryState.SubCategoryId,
                            SubCategoryName = currentCategoryState.SubCategoryName,
                            Options = availableStatuses.Select(s => s.Name).ToList()
                        },
                        actionIntent = "SHOW_DISH_STATUS_OPTIONS",
                        categoryOptions = availableStatuses.Select((s, idx) => $"{idx + 1}. {s.Name}").ToList(),
                        products = new List<object>(),
                        stores = new List<object>()
                    });
                }

                // NẾU NHẬP ĐÚNG: TRUY XUẤT SẢN PHẨM THẬT TRONG DATABASE ĐÃ ĐƯỢC DUYỆT (APPROVED)
                var allDbProds = await GetCachedActiveProductsAsync();
                var filteredProds = FilterApprovedProductsByCategory(allDbProds, catDef.Id, currentCategoryState.SubCategoryId, matchedStatus.Id);

                if (filteredProds.Count == 0)
                {
                    filteredProds = allDbProds.Where(p => p.AiStatus == "approved" && p.StockStatus != "out_of_stock").Take(6).ToList();
                }

                var sbFinal = new StringBuilder();
                sbFinal.AppendLine($"<i class=\"bi bi-check-circle-fill text-success me-1\"></i> Dạ đây là các sản phẩm thuộc phân loại **{catDef.Name}** > nhóm hàng **{currentCategoryState.SubCategoryName}** > trạng thái **{matchedStatus.Name}** tươi ngon, đã được kiểm duyệt an toàn trên sàn ZoneMart để bạn tham khảo nhé: {catDef.Icon}");
                sbFinal.AppendLine();

                for (int i = 0; i < Math.Min(filteredProds.Count, 6); i++)
                {
                    var p = filteredProds[i];
                    sbFinal.AppendLine($"{i + 1}. **{p.ProductName}** ({p.Price:N0}đ) - Gian hàng: *{p.StoreName ?? "ZoneMart Store"}*");
                }

                sbFinal.AppendLine();
                sbFinal.AppendLine("<i class=\"bi bi-arrow-right-circle-fill text-primary me-1\"></i> **Bạn muốn đặt món nào trong nhóm hàng trên không ạ?** (Nhắn tên món hoặc số 1, 2, 3... để mình hỗ trợ lên đơn hỏa tốc giao ngay trong 20-30 phút nhé!)");

                return Ok(new
                {
                    success = true,
                    reply = sbFinal.ToString(),
                    provider = "ZoneMart Category Service",
                    categoryState = new CategoryBrowseStateDto { Step = "NONE" },
                    actionIntent = (string?)null,
                    orderState = new OrderStateDto
                    {
                        Step = "AWAITING_ITEM_NAME",
                        CartItems = new List<OrderItemDto>()
                    },
                    products = filteredProds.Take(6).Select(p => (object)new
                    {
                        id = p.Id,
                        name = p.ProductName,
                        price = p.Price,
                        storeName = p.StoreName ?? "ZoneMart Store",
                        image = !string.IsNullOrWhiteSpace(p.ImageUrl) ? p.ImageUrl : "/images/anhxoanen.png"
                    }).ToList(),
                    stores = new List<object>()
                });
            }

            // =========================================================================
            // GIAI ĐOẠN 2: NGƯỜI DÙNG ĐANG TRONG TRẠNG THÁI CHỜ CHỌN NHÓM HÀNG (AWAITING_SUBCATEGORY)
            // =========================================================================
            if (activeStep == "AWAITING_SUBCATEGORY")
            {
                if (isCancelCmd)
                {
                    return Ok(new
                    {
                        success = true,
                        reply = "Dạ mình đã hủy luồng gợi ý phân loại sản phẩm rồi nhé! Bây giờ bạn có thể trò chuyện hoặc hỏi mình các thông tin khác bất cứ lúc nào ạ!",
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto { Step = "NONE" },
                        actionIntent = (string?)null
                    });
                }

                string currentCatId = !string.IsNullOrWhiteSpace(currentCategoryState.CategoryId)
                    ? currentCategoryState.CategoryId
                    : "beverage";

                var catDef = _categoryDefinitions.FirstOrDefault(d => d.Id == currentCatId)
                             ?? _categoryDefinitions.First(d => d.Id == "beverage");

                // Khớp nhóm hàng theo số thứ tự (1, 2, 3...) hoặc tên
                CategoryBrowseOption? matchedSubCat = null;
                var numMatch = Regex.Match(cleanMsgNoTone, @"\b([1-9])\b");
                if (numMatch.Success && int.TryParse(numMatch.Groups[1].Value, out int selectedIdx))
                {
                    if (selectedIdx >= 1 && selectedIdx <= catDef.SubCategories.Count)
                    {
                        matchedSubCat = catDef.SubCategories[selectedIdx - 1];
                    }
                }

                if (matchedSubCat == null)
                {
                    foreach (var sub in catDef.SubCategories)
                    {
                        string subNameClean = RemoveVietnameseTones(sub.Name).ToLower();
                        if (cleanMsgNoTone.Contains(subNameClean) || subNameClean.Contains(cleanMsgNoTone))
                        {
                            matchedSubCat = sub;
                            break;
                        }

                        foreach (var kw in sub.MatchKeywords)
                        {
                            if (cleanMsgNoTone.Contains(kw))
                            {
                                matchedSubCat = sub;
                                break;
                            }
                        }
                        if (matchedSubCat != null) break;
                    }
                }

                // NẾU NHẬP SAI: BẮT BUỘC HỎI LẠI ĐẾN KHI NHẬP ĐÚNG HOẶC NHẬP HỦY
                if (matchedSubCat == null)
                {
                    var sbError = new StringBuilder();
                    sbError.AppendLine($"<i class=\"bi bi-exclamation-triangle-fill text-warning me-1\"></i> Dạ lựa chọn của bạn chưa chính xác trong nhóm hàng của phân loại **{catDef.Name}** rồi ạ!");
                    sbError.AppendLine();
                    sbError.AppendLine($"Hiện tại phân loại **{catDef.Name}** gồm các nhóm hàng sau:");
                    for (int i = 0; i < catDef.SubCategories.Count; i++)
                    {
                        sbError.AppendLine($"{i + 1}. {catDef.SubCategories[i].Icon} **{catDef.SubCategories[i].Name}**");
                    }
                    sbError.AppendLine();
                    sbError.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn nhóm hàng nào ạ?**");
                    sbError.AppendLine("*(Bạn vui lòng chọn đúng **số thứ tự (1, 2, 3...)** hoặc gõ đúng **tên nhóm hàng** ở trên nhé! Nhắn **'hủy'** để dừng luồng gợi ý đồ ạ)*");

                    return Ok(new
                    {
                        success = true,
                        reply = sbError.ToString(),
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto
                        {
                            Step = "AWAITING_SUBCATEGORY",
                            CategoryId = catDef.Id,
                            CategoryName = catDef.Name,
                            Options = catDef.SubCategories.Select(s => s.Name).ToList()
                        },
                        actionIntent = "SHOW_SUBCATEGORY_OPTIONS",
                        categoryOptions = catDef.SubCategories.Select((s, idx) => $"{idx + 1}. {s.Name}").ToList(),
                        products = new List<object>(),
                        stores = new List<object>()
                    });
                }

                // NẾU NHẬP ĐÚNG: CHUYỂN SANG BƯỚC HỎI TRẠNG THÁI MÓN (AWAITING_DISH_STATUS)
                var availableStatuses = catDef.DishStatuses.Count > 0
                    ? catDef.DishStatuses
                    : new List<CategoryBrowseOption> { new CategoryBrowseOption { Id = "all", Name = "Tất cả trạng thái", Icon = "<i class=\"bi bi-layers-fill\"></i>" } };

                var sbStatusPrompt = new StringBuilder();
                sbStatusPrompt.AppendLine($"Dạ bạn đã chọn nhóm hàng **{matchedSubCat.Name}** ({catDef.Name})! <i class=\"bi bi-check-circle-fill text-success me-1\"></i>");
                sbStatusPrompt.AppendLine();
                sbStatusPrompt.AppendLine($"Hiện tại phân loại **{catDef.Name}** gồm các trạng thái món sau:");
                for (int i = 0; i < availableStatuses.Count; i++)
                {
                    sbStatusPrompt.AppendLine($"{i + 1}. {availableStatuses[i].Icon} **{availableStatuses[i].Name}**");
                }
                sbStatusPrompt.AppendLine();
                sbStatusPrompt.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn trạng thái món nào ạ?**");
                sbStatusPrompt.AppendLine("*(Bạn vui lòng chọn đúng **số thứ tự (1, 2, 3...)** hoặc gõ đúng **tên trạng thái món** ở trên nhé! Nhắn **'hủy'** nếu muốn dừng luồng gợi ý đồ ạ)*");

                return Ok(new
                {
                    success = true,
                    reply = sbStatusPrompt.ToString(),
                    provider = "ZoneMart Category Service",
                    categoryState = new CategoryBrowseStateDto
                    {
                        Step = "AWAITING_DISH_STATUS",
                        CategoryId = catDef.Id,
                        CategoryName = catDef.Name,
                        SubCategoryId = matchedSubCat.Id,
                        SubCategoryName = matchedSubCat.Name,
                        Options = availableStatuses.Select(s => s.Name).ToList()
                    },
                    actionIntent = "SHOW_DISH_STATUS_OPTIONS",
                    categoryOptions = availableStatuses.Select((s, idx) => $"{idx + 1}. {s.Name}").ToList(),
                    products = new List<object>(),
                    stores = new List<object>()
                });
            }

            // =========================================================================
            // GIAI ĐOẠN 3: NGƯỜI DÙNG ĐANG TRONG TRẠNG THÁI CHỜ CHỌN NGÀNH HÀNG CHÍNH (AWAITING_MAIN_CATEGORY)
            // =========================================================================
            if (activeStep == "AWAITING_MAIN_CATEGORY")
            {
                if (isCancelCmd)
                {
                    return Ok(new
                    {
                        success = true,
                        reply = "Dạ mình đã hủy luồng gợi ý phân loại sản phẩm rồi nhé! Bây giờ bạn có thể trò chuyện hoặc hỏi mình các thông tin khác bất cứ lúc nào ạ!",
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto { Step = "NONE" },
                        actionIntent = (string?)null
                    });
                }

                // Khớp ngành hàng chính 1-5 hoặc theo tên
                CategoryBrowseDefinition? chosenCat = null;
                var numMatch = Regex.Match(cleanMsgNoTone, @"\b([1-5])\b");
                if (numMatch.Success && int.TryParse(numMatch.Groups[1].Value, out int catIdx))
                {
                    if (catIdx >= 1 && catIdx <= _categoryDefinitions.Count)
                    {
                        chosenCat = _categoryDefinitions[catIdx - 1];
                    }
                }

                if (chosenCat == null)
                {
                    chosenCat = MatchCategoryDefinition(cleanMsgNoTone);
                }

                if (chosenCat == null)
                {
                    var sbErr = new StringBuilder();
                    sbErr.AppendLine("<i class=\"bi bi-exclamation-triangle-fill text-warning me-1\"></i> Dạ lựa chọn của bạn chưa chính xác. Vui lòng chọn đúng một trong các phân loại sau trên sàn ZoneMart:");
                    sbErr.AppendLine();
                    for (int i = 0; i < _categoryDefinitions.Count; i++)
                    {
                        sbErr.AppendLine($"{i + 1}. {_categoryDefinitions[i].Icon} **{_categoryDefinitions[i].Name}**");
                    }
                    sbErr.AppendLine();
                    sbErr.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn phân loại nào ạ?**");
                    sbErr.AppendLine("*(Bạn vui lòng nhắn **số thứ tự (1 - 5)** hoặc **tên phân loại** nhé! Nhắn **'hủy'** nếu muốn dừng lại)*");

                    return Ok(new
                    {
                        success = true,
                        reply = sbErr.ToString(),
                        provider = "ZoneMart Category Service",
                        categoryState = new CategoryBrowseStateDto { Step = "AWAITING_MAIN_CATEGORY" },
                        actionIntent = "SHOW_MAIN_CATEGORY_OPTIONS",
                        categoryOptions = _categoryDefinitions.Select((c, idx) => $"{idx + 1}. {c.Name}").ToList(),
                        products = new List<object>(),
                        stores = new List<object>()
                    });
                }

                // Chuyển sang bước hỏi nhóm hàng của phân loại vừa chọn
                var sbPrompt = new StringBuilder();
                sbPrompt.AppendLine($"Dạ bạn đang chọn phân loại **{chosenCat.Name}**! {chosenCat.Icon}");
                sbPrompt.AppendLine();
                sbPrompt.AppendLine($"Hiện tại phân loại **{chosenCat.Name}** trên sàn ZoneMart gồm các nhóm hàng sau:");
                for (int i = 0; i < chosenCat.SubCategories.Count; i++)
                {
                    sbPrompt.AppendLine($"{i + 1}. {chosenCat.SubCategories[i].Icon} **{chosenCat.SubCategories[i].Name}**");
                }
                sbPrompt.AppendLine();
                sbPrompt.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn nhóm hàng nào ạ?**");
                sbPrompt.AppendLine("*(Bạn vui lòng chọn đúng **số thứ tự (1, 2, 3...)** hoặc gõ đúng **tên nhóm hàng** ở trên nhé! Nhắn **'hủy'** nếu muốn dừng lại)*");

                return Ok(new
                {
                    success = true,
                    reply = sbPrompt.ToString(),
                    provider = "ZoneMart Category Service",
                    categoryState = new CategoryBrowseStateDto
                    {
                        Step = "AWAITING_SUBCATEGORY",
                        CategoryId = chosenCat.Id,
                        CategoryName = chosenCat.Name,
                        Options = chosenCat.SubCategories.Select(s => s.Name).ToList()
                    },
                    actionIntent = "SHOW_SUBCATEGORY_OPTIONS",
                    categoryOptions = chosenCat.SubCategories.Select((s, idx) => $"{idx + 1}. {s.Name}").ToList(),
                    products = new List<object>(),
                    stores = new List<object>()
                });
            }

            // =========================================================================
            // GIAI ĐOẠN 4: KHỞI TẠO LUỒNG PHÂN LOẠI NGÀNH HÀNG / DANH MỤC
            // =========================================================================

            // Trường hợp 4A: Người dùng hỏi chung chung về các phân loại trên web ("gợi ý phân loại đồ trong web", "các phân loại", "phân loại hàng"...)
            if (IsGeneralCategoryOverviewQuery(cleanMsgNoTone))
            {
                var sbAll = new StringBuilder();
                sbAll.AppendLine("Dạ trên sàn ZoneMart hiện có **5 phân loại ngành hàng chính** với đầy đủ các sản phẩm tươi ngon chuẩn sạch đã được kiểm duyệt: <i class=\"bi bi-bag-check-fill text-primary me-1\"></i>");
                sbAll.AppendLine();
                for (int i = 0; i < _categoryDefinitions.Count; i++)
                {
                    var cd = _categoryDefinitions[i];
                    sbAll.AppendLine($"{i + 1}. {cd.Icon} **{cd.Name}**");
                }
                sbAll.AppendLine();
                sbAll.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn xem chi tiết phân loại nào ạ?**");
                sbAll.AppendLine("*(Bạn hãy nhắn **số thứ tự (1, 2, 3, 4, 5)** hoặc **tên phân loại** ở trên nhé! Nhắn **'hủy'** nếu muốn dừng lại)*");

                return Ok(new
                {
                    success = true,
                    reply = sbAll.ToString(),
                    provider = "ZoneMart Category Service",
                    categoryState = new CategoryBrowseStateDto { Step = "AWAITING_MAIN_CATEGORY" },
                    actionIntent = "SHOW_MAIN_CATEGORY_OPTIONS",
                    categoryOptions = _categoryDefinitions.Select((c, idx) => $"{idx + 1}. {c.Name}").ToList(),
                    products = new List<object>(),
                    stores = new List<object>()
                });
            }

            // Trường hợp 4B: Người dùng hỏi trực tiếp một phân loại cụ thể
            // (VÍ DỤ: "tôi muốn xem đồ uống", "tôi muốn xem những đồ ăn tươi", "xem rau củ", "đồ ăn nóng"...)
            var matchedCategory = MatchCategoryDefinition(cleanMsgNoTone);
            if (matchedCategory != null)
            {
                var sbSubPrompt = new StringBuilder();
                sbSubPrompt.AppendLine($"Dạ bạn đang muốn xem các món trong phân loại **{matchedCategory.Name}** đúng không ạ! {matchedCategory.Icon}");
                sbSubPrompt.AppendLine();
                sbSubPrompt.AppendLine($"Hiện tại phân loại **{matchedCategory.Name}** trên sàn ZoneMart gồm các nhóm hàng sau:");
                for (int i = 0; i < matchedCategory.SubCategories.Count; i++)
                {
                    sbSubPrompt.AppendLine($"{i + 1}. {matchedCategory.SubCategories[i].Icon} **{matchedCategory.SubCategories[i].Name}**");
                }
                sbSubPrompt.AppendLine();
                sbSubPrompt.AppendLine("<i class=\"bi bi-patch-question-fill text-warning me-1\"></i> **Bạn muốn chọn nhóm hàng nào ạ?**");
                sbSubPrompt.AppendLine("*(Bạn vui lòng nhắn **số thứ tự (1, 2, 3...)** hoặc **tên nhóm hàng** ở trên để mình hỗ trợ nhé! Nhắn **'hủy'** nếu muốn dừng lại)*");

                return Ok(new
                {
                    success = true,
                    reply = sbSubPrompt.ToString(),
                    provider = "ZoneMart Category Service",
                    categoryState = new CategoryBrowseStateDto
                    {
                        Step = "AWAITING_SUBCATEGORY",
                        CategoryId = matchedCategory.Id,
                        CategoryName = matchedCategory.Name,
                        Options = matchedCategory.SubCategories.Select(s => s.Name).ToList()
                    },
                    actionIntent = "SHOW_SUBCATEGORY_OPTIONS",
                    categoryOptions = matchedCategory.SubCategories.Select((s, idx) => $"{idx + 1}. {s.Name}").ToList(),
                    products = new List<object>(),
                    stores = new List<object>()
                });
            }

            return null;
        }


        private async Task<List<Product>> SearchProductsInDatabaseAsync(string cleanMsgNoTone)



        {



            try



            {



                var allProducts = await GetCachedActiveProductsAsync();



                if (allProducts == null || allProducts.Count == 0) return new List<Product>();







                // Nếu là câu hỏi đặt đồ chung chung chưa có món -> Tuyệt đối không tự động chọn bừa sản phẩm trong DB



                if (IsGeneralOrderingPrompt(cleanMsgNoTone))



                {



                    return new List<Product>();



                }







                // Nếu là câu hỏi về thời tiết se lạnh / món ăn ấm nóng -> Ưu tiên trả về các món ăn nóng hổi



                if (IsColdWeatherIntent(cleanMsgNoTone))



                {



                    var warmItems = allProducts.Where(IsProductWarming)



                        .OrderByDescending(p => { var s = GetProductPopularityStats(p); return s.Sold + (s.Rating * 100); })



                        .ToList();



                    if (warmItems.Count > 0) return warmItems;



                }







                // Nếu là câu hỏi về thời tiết nắng nóng / món giải nhiệt, mát lạnh -> Ưu tiên trả về các món mát giải nhiệt



                if (IsHotWeatherIntent(cleanMsgNoTone))



                {



                    var coldItems = allProducts.Where(IsProductCooling)



                        .OrderByDescending(p => { var s = GetProductPopularityStats(p); return s.Sold + (s.Rating * 100); })



                        .ToList();



                    if (coldItems.Count > 0) return coldItems;



                }







                // BÓC TÁCH TỪ KHÓA THEO TỪ NEO "về", "đồ", "tên", "loại" VÀ TIỀN TỐ XEM HÀNG



                string extractedKw = ExtractSearchKeyword(cleanMsgNoTone);



                string searchTarget = !string.IsNullOrWhiteSpace(extractedKw) ? extractedKw : cleanMsgNoTone;



                searchTarget = searchTarget.Replace("banh my", "banh mi").Trim();







                var kwWords = searchTarget.Split(' ', StringSplitOptions.RemoveEmptyEntries)



                    .Where(w => w.Length >= 2)



                    .ToList();







                var matchedMap = new Dictionary<string, Product>();







                // 1. Khớp Category (phân loại): người dùng không cần nhập đủ tên phân loại



                // Ví dụ: 'thuc pham tuoi', 'tuoi', 'rau cu', 'trai cay', 'do uong', 'mon an nong'...



                foreach (var p in allProducts)



                {



                    string pCat = RemoveVietnameseTones(p.Category ?? "").ToLower();



                    bool catMatch = false;



                    if (!string.IsNullOrWhiteSpace(searchTarget) && searchTarget.Length >= 2)



                    {



                        if (searchTarget.Length <= 4)



                        {



                            catMatch = Regex.IsMatch(pCat, $@"\b{Regex.Escape(searchTarget)}\b");



                        }



                        else



                        {



                            catMatch = pCat.Contains(searchTarget) || searchTarget.Contains(pCat);



                        }



                    }







                    if (!catMatch && kwWords.Count > 0)



                    {



                        catMatch = kwWords.All(w => Regex.IsMatch(pCat, $@"\b{Regex.Escape(w)}\b") || pCat.Contains(w));



                    }







                    if (catMatch && !string.IsNullOrEmpty(p.Id))



                    {



                        matchedMap[p.Id] = p;



                    }



                }







                // 2. Khớp Tên món ăn (ProductName)



                // Ví dụ: 'com' -> 'Cơm Gà Xối Mỡ...', 'Cơm Tấm Sườn Bì Chả...'



                foreach (var p in allProducts)



                {



                    string pName = RemoveVietnameseTones(p.ProductName ?? "").ToLower();



                    bool nameMatch = false;







                    if (!string.IsNullOrWhiteSpace(searchTarget) && searchTarget.Length >= 2)



                    {



                        if (searchTarget.Length <= 4)



                        {



                            // Ranh giới từ cho các từ ngắn như 'com', 'bo', 'ga', 'ca', 'tom' để không khớp nhầm 'combo'



                            nameMatch = Regex.IsMatch(pName, $@"\b{Regex.Escape(searchTarget)}\b");



                        }



                        else



                        {



                            nameMatch = pName.Contains(searchTarget);



                        }



                    }







                    if (!nameMatch && kwWords.Count > 1)



                    {



                        nameMatch = kwWords.All(w => Regex.IsMatch(pName, $@"\b{Regex.Escape(w)}\b"));



                    }







                    if (nameMatch && !string.IsNullOrEmpty(p.Id))



                    {



                        matchedMap[p.Id] = p;



                    }



                }







                // 3. Fallback: Nếu chưa tìm thấy và kwWords có từ, thử so khớp từng từ



                if (matchedMap.Count == 0 && kwWords.Count > 0)



                {



                    foreach (var p in allProducts)



                    {



                        string pName = RemoveVietnameseTones(p.ProductName ?? "").ToLower();



                        string pCat = RemoveVietnameseTones(p.Category ?? "").ToLower();



                        bool anyMatch = kwWords.Any(w => Regex.IsMatch(pName, $@"\b{Regex.Escape(w)}\b") || Regex.IsMatch(pCat, $@"\b{Regex.Escape(w)}\b"));



                        if (anyMatch && !string.IsNullOrEmpty(p.Id))



                        {



                            matchedMap[p.Id] = p;



                        }



                    }



                }







                var resultList = matchedMap.Values.ToList();







                // SẮP XẾP: Theo số lượt người mua (Đã bán) và Hot / Đánh giá (Rating) từ cao xuống thấp



                resultList = resultList.OrderByDescending(p =>



                {



                    var stats = GetProductPopularityStats(p);



                    return stats.Sold + (stats.Rating * 100);



                }).ToList();







                return resultList;



            }



            catch (Exception ex)



            {



                Console.WriteLine($"⚠️ [SearchProductsInDatabaseAsync Error] {ex.Message}");



                return new List<Product>();



            }



        }







        private bool IsSmartCartOperation(string cleanMsgNoTone, List<OrderItemDto>? cartItems)



        {



            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;







            // Nếu người dùng đang hỏi xem sản phẩm / duyệt thực đơn -> KHÔNG PHẢI THAO TÁC GIỎ HÀNG!



            if (IsProductBrowseOrSearchIntent(cleanMsgNoTone)) return false;







            // 1. Phải có từ khóa thao tác giỏ hàng: bỏ, bớt, trừ, giảm, xóa, loại bỏ, thêm, cộng, tăng, cho, lấy, đặt, mua



            bool isBeef = cleanMsgNoTone.Contains("thit bo") || cleanMsgNoTone.Contains("bo my") || cleanMsgNoTone.Contains("bo uc") ||



                          cleanMsgNoTone.Contains("bo xao") || cleanMsgNoTone.Contains("bo kho") || cleanMsgNoTone.Contains("bo nuong") ||



                          cleanMsgNoTone.Contains("bo luc lac") || cleanMsgNoTone.Contains("bo bit tet") || cleanMsgNoTone.Contains("bo vien");







            bool hasActionKw = cleanMsgNoTone.Contains("bot") || cleanMsgNoTone.Contains("giam") || cleanMsgNoTone.Contains("tru") ||



                               Regex.IsMatch(cleanMsgNoTone, @"\b(xoa|xoa\s*bo|loai\s*bo)\b") ||



                               cleanMsgNoTone.Contains("them") || cleanMsgNoTone.Contains("cong") || cleanMsgNoTone.Contains("tang") ||



                               cleanMsgNoTone.Contains("nua") || cleanMsgNoTone.StartsWith("cho ") || cleanMsgNoTone.Contains(" cho ") ||



                               cleanMsgNoTone.StartsWith("lay ") || cleanMsgNoTone.Contains(" lay ") ||



                               cleanMsgNoTone.StartsWith("dat ") || cleanMsgNoTone.Contains(" dat ") ||



                               cleanMsgNoTone.StartsWith("mua ") || cleanMsgNoTone.Contains(" mua ") ||



                               (Regex.IsMatch(cleanMsgNoTone, @"\bbo\b") && !isBeef);







            // 2. Hoặc câu ghép có liên từ nối và có số lượng



            bool hasConjunctionWithQty = (cleanMsgNoTone.Contains(" va ") || cleanMsgNoTone.Contains(",") || cleanMsgNoTone.Contains(";") || cleanMsgNoTone.Contains(" hoac ") || cleanMsgNoTone.Contains(" + ") || cleanMsgNoTone.Contains(" voi ") || cleanMsgNoTone.Contains(" them ")) &&



                                         Regex.IsMatch(cleanMsgNoTone, @"\b\d+\b");







            return hasActionKw || hasConjunctionWithQty;



        }







        private async Task<OrderItemDto?> FindBestMatchingCartItemAsync(List<OrderItemDto> cartItems, string segTerm)



        {



            if (cartItems == null || cartItems.Count == 0) return null;







            if (string.IsNullOrWhiteSpace(segTerm))



            {



                return cartItems.Count == 1 ? cartItems[0] : null;



            }







            string normSegTerm = RemoveVietnameseTones(segTerm.ToLower().Trim());







            // 1. Đại từ thay thế: 'nó', 'món này', 'món đó', 'sản phẩm này'



            var pronouns = new HashSet<string> { "no", "mon nay", "mon do", "san pham nay", "mon da chon", "mon tren" };



            if (pronouns.Contains(normSegTerm))



            {



                return cartItems.Count == 1 ? cartItems[0] : null;



            }







            // 2. So khớp trực tiếp chuỗi hoặc chuỗi con (nếu độ dài đủ tin cậy >= 4 ký tự)



            foreach (var it in cartItems)



            {



                string itNorm = RemoveVietnameseTones(it.ProductName.ToLower().Trim());



                if (itNorm == normSegTerm || (normSegTerm.Length >= 5 && itNorm.Contains(normSegTerm)))



                {



                    return it;



                }



            }







            // 3. So khớp từ khóa đặc trưng (Distinguishing Keywords)



            // Danh sách từ loại chung chung không dùng đơn lẻ để gộp 2 món khác nhau:



            var genericBaseWords = new HashSet<string>



            {



                "com", "banh", "rau", "thit", "nuoc", "sua", "tra", "ca", "do", "mon",



                "an", "uong", "hop", "dia", "to", "bat", "khay", "tui", "kg", "g",



                "tuoi", "sach", "nong", "hoi", "dac", "biet", "loai", "chuan"



            };







            var fillerWords = new HashSet<string>



            {



                "mon", "phan", "suat", "hop", "cai", "lon", "chai", "cho", "lay", "dum",



                "giup", "ho", "di", "nhe", "nha", "nua", "vao", "gio", "hang", "them", "bot",



                "giam", "tru", "bo", "xoa", "so", "luong", "thanh", "doi", "chinh", "toi",



                "em", "anh", "chi", "con", "trai", "dia", "to", "bat"



            };







            var segWords = normSegTerm.Split(' ', StringSplitOptions.RemoveEmptyEntries)



                .Where(w => w.Length >= 2 && !fillerWords.Contains(w))



                .ToList();







            var specificSegWords = segWords.Where(w => !genericBaseWords.Contains(w)).ToList();







            OrderItemDto? bestItem = null;



            double maxMatchScore = 0;







            if (segWords.Count > 0)



            {



                foreach (var it in cartItems)



                {



                    string itNorm = RemoveVietnameseTones(it.ProductName.ToLower().Trim());



                    var itWords = itNorm.Split(' ', StringSplitOptions.RemoveEmptyEntries).ToHashSet();







                    // NẾU TỪ KHÓA CÓ TỪ ĐẶC TRƯNG (ví dụ: 'tam', 'suon' trong 'com tam suon')



                    if (specificSegWords.Count > 0)



                    {



                        int specificMatches = specificSegWords.Count(w => itWords.Contains(w));



                        // Nếu không có từ đặc trưng nào khớp (ví dụ: 'tam', 'suon' hoàn toàn không có trong 'com ga xoi mo') -> TUYỆT ĐỐI KHÔNG KHỚP!



                        if (specificMatches == 0) continue;







                        double specificRatio = (double)specificMatches / specificSegWords.Count;



                        if (specificRatio >= 0.5)



                        {



                            int totalMatches = segWords.Count(w => itWords.Contains(w));



                            double totalScore = (specificRatio * 100) + totalMatches;



                            if (totalScore > maxMatchScore)



                            {



                                maxMatchScore = totalScore;



                                bestItem = it;



                            }



                        }



                    }



                    else



                    {



                        // Chỉ gồm từ loại chung (ví dụ: 'com') -> Chỉ khớp nếu trong giỏ hàng duy nhất có 1 món cơm



                        int genericMatches = segWords.Count(w => itWords.Contains(w));



                        if (genericMatches == segWords.Count && cartItems.Count == 1)



                        {



                            return it;



                        }



                    }



                }



            }







            if (bestItem != null)



            {



                return bestItem;



            }







            // 4. Fallback truy vấn Database tương quan: Chỉ kiểm tra Món Khớp Số 1 (Top 1) trong DB có trong giỏ hàng không



            try



            {



                var dbMatches = await SearchProductsInDatabaseAsync(normSegTerm);



                if (dbMatches != null && dbMatches.Count > 0)



                {



                    var topMatch = dbMatches.First();



                    var inCart = cartItems.FirstOrDefault(it => it.ProductId == topMatch.Id ||



                        RemoveVietnameseTones(it.ProductName.ToLower()) == RemoveVietnameseTones((topMatch.ProductName ?? "").ToLower()));



                    if (inCart != null)



                    {



                        return inCart;



                    }



                }



            }



            catch { }







            // TUYỆT ĐỐI KHÔNG tự động trả về cartItems[0] nếu người dùng đã chỉ định tên món cụ thể mà không khớp!



            return null;



        }







