        private static bool IsNonFoodOrSlang(string cleanMsgNoTone)



        {



            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;







            string[] slangWords = new[]



            {



                "an don", "don", "danh nhau", "chui", "chui bay", "buon ngu", "ngu quen", "truot", "truot mon",



                "truot dai hoc", "that tinh", "bay mau", "hoc lai", "chay tui", "het tien", "game", "laptop",



                "dien thoai", "may tinh", "quan ao", "giay dep", "xe may", "ngu ngo", "ao tuong", "di ngu", "thao cuoc"



            };







            bool hasSlang = slangWords.Any(w => Regex.IsMatch(cleanMsgNoTone, $@"\b{Regex.Escape(w)}\b"));



            if (!hasSlang) return false;







            // Kiểm tra xem có từ chỉ đồ ăn thức uống ẩm thực hay không



            string[] foodWords = new[]



            {



                "thit", "ca", "ga", "bo", "heo", "tom", "muc", "ech", "vit", "hai san",



                "lau", "nuong", "com", "bun", "pho", "mi", "banh", "che", "tra", "sup",



                "chao", "canh", "rau", "cu", "qua", "xao", "kho", "chien", "nam", "do an", "mon an"



            };







            bool hasFood = foodWords.Any(fw => Regex.IsMatch(cleanMsgNoTone, $@"\b{Regex.Escape(fw)}\b"));



            return !hasFood;



        }







