        private static bool IsComboOrderIntent(string cleanMsgNoTone, string userMsg = "")



        {



            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;

            if (IsCategoryBrowseIntent(cleanMsgNoTone, userMsg)) return false;



            if (cleanMsgNoTone.Contains("phan loai") || cleanMsgNoTone.Contains("do an tuoi") ||

                cleanMsgNoTone.Contains("thuc pham tuoi") || cleanMsgNoTone.Contains("muon xem nhung do an tuoi") ||

                cleanMsgNoTone.Contains("muon xem do an tuoi"))

            {

                return false;

            }



            if (cleanMsgNoTone.Contains("an kem") || cleanMsgNoTone.Contains("mon an kem") ||

                cleanMsgNoTone.Contains("do an kem") || cleanMsgNoTone.Contains("kem voi") ||

                cleanMsgNoTone.Contains("kem theo") || cleanMsgNoTone.Contains("kem gi") ||

                cleanMsgNoTone.Contains("kem mon") || cleanMsgNoTone.Contains("topping"))

            {

                return false;

            }







            // BỔ SUNG QUY TẮC BẮT BUỘC: Cứ nói đến "thực đơn", "lên thực đơn", "mâm cỗ", "mâm cơm", "combo", "đãi tiệc", "đãi họ hàng"...



            // thì TUYỆT ĐỐI ƯU TIÊN VÀO LUỒNG COMBO (kể cả có số lượng như "cho tôi đặt 3 mâm cỗ", "lên thực đơn 5 mâm...")



            bool hasMenuOrComboKeyword = cleanMsgNoTone.Contains("combo") ||



                                         cleanMsgNoTone.Contains("sieu day du") ||



                                         cleanMsgNoTone.Contains("di cho ho") ||



                                         cleanMsgNoTone.Contains("gom do") ||



                                         cleanMsgNoTone.Contains("thuc don") ||



                                         cleanMsgNoTone.Contains("len thuc don") ||



                                         cleanMsgNoTone.Contains("goi y thuc don") ||



                                         cleanMsgNoTone.Contains("thuc don cho") ||



                                         cleanMsgNoTone.Contains("thuc don nhu nao") ||



                                         cleanMsgNoTone.Contains("mam co") ||



                                         cleanMsgNoTone.Contains("mam com") ||



                                         cleanMsgNoTone.Contains("dai ho hang") ||



                                         cleanMsgNoTone.Contains("dai tiec") ||



                                         cleanMsgNoTone.Contains("bua tiec") ||



                                         cleanMsgNoTone.Contains("an tiec") ||



                                         cleanMsgNoTone.Contains("loi lau") ||



                                         cleanMsgNoTone.Contains("noi lau") ||



                                         cleanMsgNoTone.Contains("lau ech") ||



                                         cleanMsgNoTone.Contains("set lau") ||



                                         cleanMsgNoTone.Contains("set nuong") ||



                                         cleanMsgNoTone.Contains("bua lau") ||



                                         cleanMsgNoTone.Contains("bua nuong") ||



                                         cleanMsgNoTone.Contains("set an") ||



                                         cleanMsgNoTone.Contains("set do an") ||



                                         cleanMsgNoTone.Contains("len mon") ||



                                         cleanMsgNoTone.Contains("bua an") ||



                                         cleanMsgNoTone.Contains("nau lau") ||



                                         cleanMsgNoTone.Contains("an lau") ||



                                         cleanMsgNoTone.Contains("an nuong") ||



                                         cleanMsgNoTone.Contains("nau nuong") ||



                                         cleanMsgNoTone.Contains("set do") ||



                                         cleanMsgNoTone.Contains("set thuc pham") ||



                                         cleanMsgNoTone.Contains("tron goi") ||



                                         cleanMsgNoTone.Contains("nguyen lieu") ||



                                         cleanMsgNoTone.Contains("giam can") ||



                                         cleanMsgNoTone.Contains("eat clean") ||



                                         cleanMsgNoTone.Contains("an kieng") ||



                                         cleanMsgNoTone.Contains("tang can") ||



                                         cleanMsgNoTone.Contains("healthy") ||



                                         cleanMsgNoTone.Contains("dinh duong");







            if (hasMenuOrComboKeyword)



            {



                return true;



            }







            // Nếu câu là lệnh đặt mua hàng trực tiếp với số lượng rõ ràng cho món lẻ thông thường (vd: "cho 2 bánh mì chảo", "lấy 1 thịt bò") -> KHÔNG cướp luồng combo



            if (Regex.IsMatch(cleanMsgNoTone, @"\b(?:cho|lay|mua|dat)\s+\d+\s+"))



            {



                return false;



            }







            // 2. Regex nhận diện câu đặt combo/nồi lẩu/set nướng/món ăn ẩm thực ngẫu nhiên



            if (Regex.IsMatch(cleanMsgNoTone, @"\b(?:dat|cho|nau|lam|muon\s+dat|muon\s+an|len|goi\s+y|chuan\s+bi)\s+(?:1\s+)?(?:loi\s+lau|noi\s+lau|set\s+lau|set\s+nuong|combo|mam\s+co|mam\s+com|bua\s+lau|bua\s+nuong|thuc\s+don|bua\s+an)\b") ||



                Regex.IsMatch(cleanMsgNoTone, @"\b(?:lau\s+\w+|nuong\s+\w+|bbq|steak|banh\s+mi\s+chao|bun\s+dau|bun\s+cha|chao\s+ech|nau\s+che|tra\s+sua)\b"))



            {



                return true;



            }







            return false;



        }







        private async Task<object?> TryProcessComboOrderAsync(ChatRequest request, string cleanMsgNoTone, string userMsg)



        {



            // 1. Nếu người dùng chỉ bấm nút hoặc hỏi chung chung về combo / thực đơn (chưa nêu cụ thể món nào)



            bool isComboGeneralInquiry = cleanMsgNoTone == "dat do an combo sieu day du" ||



                                         cleanMsgNoTone == "dat do an combo" ||



                                         cleanMsgNoTone == "combo sieu day du" ||



                                         cleanMsgNoTone == "combo" ||



                                         cleanMsgNoTone == "dat combo" ||



                                         cleanMsgNoTone == "muon dat combo" ||



                                         cleanMsgNoTone == "goi y combo" ||



                                         cleanMsgNoTone == "tu van combo" ||



                                         cleanMsgNoTone == "menu combo" ||



                                         cleanMsgNoTone == "di cho ho" ||



                                         cleanMsgNoTone == "toi muon dat combo" ||



                                         cleanMsgNoTone == "cac combo" ||



                                         cleanMsgNoTone == "thuc don" ||



                                         cleanMsgNoTone == "len thuc don" ||



                                         cleanMsgNoTone == "goi y thuc don" ||



                                         cleanMsgNoTone == "thuc don hom nay";







            if (isComboGeneralInquiry)



            {



                // NO EMOJI! Dùng icon code HTML



                return new



                {



                    success = true,



                    reply = "<i class=\"bi bi-collection-fill text-primary\"></i> Chào bạn! Bạn muốn lên thực đơn hoặc đặt combo món gì hôm nay ạ?\n\n" +



                            "ZoneMart hỗ trợ gợi ý và gom đủ mọi nguyên liệu tươi ngon nhất từ các nhà vườn cho các bữa tiệc lẩu, nướng và thực đơn gia đình:\n" +



                            "- Combo Lẩu Ếch Măng Cay Siêu Đầy Đủ\n" +



                            "- Combo Giảm Cân & Eat Clean Healthy\n" +



                            "- Combo Nướng BBQ Bò Mỹ Thượng Hạng\n" +



                            "- Combo Lẩu Gà Lá É Nấm Tươi\n" +



                            "- Combo Mâm Cơm Gia Đình Chuẩn Vị\n" +



                            "- Combo Trái Cây & Đồ Uống Giải Nhiệt Mùa Hè\n\n" +



                            "*(Bạn có thể **nhập bất kỳ combo nào bạn muốn** như Lẩu cá kèo, Lẩu vịt om sấu, Bún đậu mắm tôm, Bún chả, Nướng hải sản, Steak bò mỹ, Lẩu nấm chay... AI sẽ tự động kiểm tra và gom đủ nguyên liệu cho bạn nhé!).*\n\n" +



                            "Bạn hãy nhấn chọn món bên dưới hoặc nhắn combo bạn muốn nhé!",



                    provider = "ZoneMart AI Combo Shopper",



                    actionIntent = "SHOW_COMBO_SUGGESTIONS",



                    comboSuggestions = GetPopularComboSuggestions()



                };



            }







            // 2. Chặn các câu từ lóng hoặc nói đùa KHÔNG PHẢI ĐỒ ĂN (Ví dụ: "combo ăn đòn", "combo buồn ngủ", "combo trượt môn"...)



            if (IsNonFoodOrSlang(cleanMsgNoTone))



            {



                return new



                {



                    success = true,



                    reply = $"<i class=\"bi bi-emoji-smile text-warning\"></i> Dạ combo **'{userMsg.Trim()}'** có vẻ là một câu nói vui/troll chứ không phải là thực đơn món ăn ẩm thực có thật bạn nhỉ hihi!\n\n" +



                            "ZoneMart hiện chỉ cung cấp các combo món ăn tươi ngon, tiệc lẩu, nướng BBQ, mâm cơm gia đình và thực đơn Eat Clean chuẩn VietGAP thôi nè. Bạn hãy tham khảo các combo món ngon tuyệt đỉnh bên dưới hoặc nhắn một món ăn có thật nhé!",



                    provider = "ZoneMart AI Combo Shopper",



                    actionIntent = "SHOW_COMBO_SUGGESTIONS",



                    comboSuggestions = GetPopularComboSuggestions()



                };



            }







            // 3. Phân rã nguyên liệu cho hơn 50+ Combo ẩm thực phổ biến nhất (Fast-path Zero-latency)



            string comboName = "";



            var searchKeywords = new List<string>();







            if (TryResolveKnownCulinaryCombo(cleanMsgNoTone, userMsg, out comboName, out searchKeywords))



            {



                return await BuildComboResultFromKeywordsAsync(request, comboName, "", searchKeywords);



            }







            // 4. Cho bất kỳ món combo ngẫu nhiên nào khác hiện nay -> Gọi LLM phân tích & kiểm tra xem combo đó CÓ THẬT hay không!



            try



            {



                string llmDecomposePrompt = $@"Bạn là chuyên gia ẩm thực hàng đầu tại sàn thương mại ZoneMart. Nhiệm vụ của bạn là kiểm tra xem '{userMsg}' có phải là một món ăn, bữa ăn, nồi lẩu, set nướng, thực đơn hay combo ẩm thực CÓ THẬT trong đời sống thực tế hay không.







QUY TẮC BẮT BUỘC:



1. Nếu ĐÂY LÀ MÓN ĂN / BỮA TIỆC / THỰC ĐƠN / COMBO ẨM THỰC CÓ THẬT TRONG THỰC TẾ:



   - Đặt ""isRealFood"": true



   - ""comboName"": Tên chuẩn hóa đầy đủ, trang trọng của combo (Ví dụ: ""Combo Lẩu Cá Bớp Măng Chua Siêu Đầy Đủ"")



   - ""searchKeywords"": Danh sách 5-8 nguyên liệu thực phẩm tươi sống, rau củ, nước lẩu/sốt, gia vị, đồ ăn kèm để đi chợ.







2. Nếu KHÔNG PHẢI MÓN ĂN / ĐỒ ĂN THỰC PHẨM CÓ THẬT (ví dụ: câu nói đùa, khái niệm trừu tượng, đồ vật, từ ngữ vô nghĩa):



   - Đặt ""isRealFood"": false



   - ""rejectReason"": Giải thích ngắn gọn lý do tại sao không phải món ăn.







Trả về DUY NHẤT một chuỗi JSON hợp lệ theo định dạng sau (tuyệt đối không dùng markdown, không giải thích ngoài JSON):



{{



  ""isRealFood"": true,



  ""comboName"": ""Tên Combo"",



  ""searchKeywords"": [""nguyên liệu 1"", ""nguyên liệu 2"", ""nguyên liệu 3"", ""nguyên liệu 4"", ""nguyên liệu 5""]



}}



hoặc



{{



  ""isRealFood"": false,



  ""rejectReason"": ""Không phải là món ăn ẩm thực""



}}";







                string llmJson = await CallGroqApiAsync(llmDecomposePrompt, userMsg, null);



                if (string.IsNullOrWhiteSpace(llmJson))



                {



                    llmJson = await CallGeminiApiAsync(llmDecomposePrompt, userMsg, null);



                }







                if (!string.IsNullOrWhiteSpace(llmJson))



                {



                    llmJson = Regex.Replace(llmJson, @"^```(?:json)?\s*", "", RegexOptions.IgnoreCase);



                    llmJson = Regex.Replace(llmJson, @"\s*```$", "", RegexOptions.IgnoreCase).Trim();







                    // Kiểm tra isRealFood



                    var isRealMatch = Regex.Match(llmJson, @"""isRealFood""\s*:\s*(true|false)", RegexOptions.IgnoreCase);



                    if (isRealMatch.Success && isRealMatch.Groups[1].Value.Equals("false", StringComparison.OrdinalIgnoreCase))



                    {



                        return new



                        {



                            success = true,



                            reply = $"<i class=\"bi bi-info-circle text-primary\"></i> Dạ món/combo **'{userMsg.Trim()}'** có vẻ không phải là một món ăn hay thực đơn ẩm thực có thật trong thực tế bạn nhỉ!\n\n" +



                                    "ZoneMart hỗ trợ đầy đủ mọi combo món ăn tươi ngon, tiệc lẩu, nướng BBQ và mâm cơm gia đình. Bạn hãy tham khảo các combo sẵn có bên dưới hoặc nhắn một món ăn khác nhé!",



                            provider = "ZoneMart AI Combo Shopper",



                            actionIntent = "SHOW_COMBO_SUGGESTIONS",



                            comboSuggestions = GetPopularComboSuggestions()



                        };



                    }







                    // Trích xuất tên combo



                    var nameMatch = Regex.Match(llmJson, @"""comboName""\s*:\s*""([^""]+)""");



                    if (nameMatch.Success)



                    {



                        comboName = nameMatch.Groups[1].Value.Trim();



                    }







                    var kwMatches = Regex.Matches(llmJson, @"""([^""\r\n]{2,35})""");



                    foreach (Match m in kwMatches)



                    {



                        string val = m.Groups[1].Value.Trim();



                        if (val.Equals("comboName", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("searchKeywords", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("isRealFood", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("true", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("false", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("action", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("suggest_combo", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("replyText", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals(comboName, StringComparison.OrdinalIgnoreCase))



                        {



                            continue;



                        }



                        if (!searchKeywords.Contains(val))



                        {



                            searchKeywords.Add(val);



                        }



                    }



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[Combo LLM Parse Warning] {ex.Message}");



            }







            // 5. Kiểm tra Fallback an toàn (Ngoại tuyến / Mạng lag)



            if (searchKeywords.Count == 0)



            {



                // Kiểm tra xem câu có chứa từ ngữ ẩm thực hay không trước khi tạo fallback



                string[] culinaryKeywords = new[]



                {



                    "lau", "nuong", "com", "bun", "pho", "mi", "banh", "thit", "ca", "ga", "bo", "heo",



                    "tom", "muc", "rau", "canh", "che", "tra", "xao", "kho", "chien", "sup", "chao", "hai san"



                };







                bool hasCulinaryWord = culinaryKeywords.Any(cw => Regex.IsMatch(cleanMsgNoTone, $@"\b{Regex.Escape(cw)}\b"));



                if (!hasCulinaryWord)



                {



                    // Nếu không có bất kỳ từ ẩm thực nào -> Không phải đồ ăn thật



                    return new



                    {



                        success = true,



                        reply = $"<i class=\"bi bi-info-circle text-primary\"></i> Dạ món/combo **'{userMsg.Trim()}'** có vẻ không phải là một món ăn hay thực đơn ẩm thực có thật trong thực tế bạn nhỉ!\n\n" +



                                "ZoneMart hỗ trợ đầy đủ mọi combo món ăn tươi ngon, tiệc lẩu, nướng BBQ và mâm cơm gia đình. Bạn hãy tham khảo các combo sẵn có bên dưới nhé!",



                        provider = "ZoneMart AI Combo Shopper",



                        actionIntent = "SHOW_COMBO_SUGGESTIONS",



                        comboSuggestions = GetPopularComboSuggestions()



                    };



                }







                comboName = $"Combo {userMsg.Trim()} Siêu Đầy Đủ";



                searchKeywords = new List<string> { userMsg.Trim(), "thịt bò", "rau muống", "nấm hương", "cà chua bi", "xà lách" };



            }







            return await BuildComboResultFromKeywordsAsync(request, comboName, "", searchKeywords);



        }







        private async Task<object?> TryProcessComboOrderFromLlmReplyAsync(ChatRequest request, string llmReply, string userMsg)



        {



            try



            {



                string rawJson = llmReply.Trim();



                rawJson = Regex.Replace(rawJson, @"```(?:json)?\s*", "", RegexOptions.IgnoreCase);



                rawJson = Regex.Replace(rawJson, @"\s*```", "", RegexOptions.IgnoreCase).Trim();







                string comboName = "Combo Món Ngon Siêu Đầy Đủ";



                string replyText = "";



                var keywords = new List<string>();







                // 1. Regex bóc tách linh hoạt kể cả khi JSON bị thiếu đóng ngoặc '}'



                var cNameMatch = Regex.Match(rawJson, @"""comboName""\s*:\s*""([^""]+)""");



                if (cNameMatch.Success)



                {



                    comboName = cNameMatch.Groups[1].Value.Trim();



                }







                var rTextMatch = Regex.Match(rawJson, @"""replyText""\s*:\s*""([^""]+)""");



                if (rTextMatch.Success)



                {



                    replyText = rTextMatch.Groups[1].Value.Trim();



                }







                // Trích xuất các từ khóa nguyên liệu



                int kwIndex = rawJson.IndexOf("searchKeywords", StringComparison.OrdinalIgnoreCase);



                if (kwIndex >= 0)



                {



                    string kwPart = rawJson.Substring(kwIndex);



                    var kMatches = Regex.Matches(kwPart, @"""([^""\r\n]{2,35})""");



                    foreach (Match m in kMatches)



                    {



                        string val = m.Groups[1].Value.Trim();



                        if (val.Equals("searchKeywords", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("action", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("suggest_combo", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("comboName", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals("replyText", StringComparison.OrdinalIgnoreCase) ||



                            val.Equals(comboName, StringComparison.OrdinalIgnoreCase))



                        {



                            continue;



                        }



                        if (!keywords.Contains(val))



                        {



                            keywords.Add(val);



                        }



                    }



                }







                if (keywords.Count > 0)



                {



                    return await BuildComboResultFromKeywordsAsync(request, comboName, replyText, keywords);



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[Parse Combo LLM Error] {ex.Message}");



            }



            return null;



        }







        private static double CalculateDistanceKm(double lat1, double lon1, double lat2, double lon2)



        {



            const double R = 6371.0;



            double dLat = (lat2 - lat1) * Math.PI / 180.0;



            double dLon = (lon2 - lon1) * Math.PI / 180.0;



            double a = Math.Sin(dLat / 2.0) * Math.Sin(dLat / 2.0) +



                       Math.Cos(lat1 * Math.PI / 180.0) * Math.Cos(lat2 * Math.PI / 180.0) *



                       Math.Sin(dLon / 2.0) * Math.Sin(dLon / 2.0);



            double c = 2.0 * Math.Atan2(Math.Sqrt(a), Math.Sqrt(1.0 - a));



            return Math.Round(R * c, 1);



        }







        private async Task<object> BuildComboResultFromKeywordsAsync(ChatRequest request, string comboName, string replyIntro, List<string> searchKeywords)



        {



            List<Product> activeProducts = new();



            try



            {



                activeProducts = await _mongoService.Products



                    .Find(p => p.StockQuantity > 0 && p.StockStatus != "deleted" && p.AiStatus == "approved")



                    .ToListAsync();



            }



            catch (Exception ex)



            {



                Console.WriteLine($"[Mongo Query Error] {ex.Message}");



            }







            // Đảm bảo luôn có đầy đủ catalog sản phẩm mẫu chất lượng cao nếu Mongo chưa đủ dữ liệu



            if (activeProducts.Count < 20)



            {



                var seedList = CatalogSeedData.GetCatalogProducts();



                foreach (var sp in seedList)



                {



                    if (!activeProducts.Any(ap => ap.Id == sp.Id || ap.ProductName == sp.ProductName))



                    {



                        activeProducts.Add(sp);



                    }



                }



            }







            var comboItems = new List<ComboItemDto>();



            var missingItems = new List<string>();



            var usedProductIds = new HashSet<string>();







            foreach (var kw in searchKeywords)



            {



                string kwNoTone = RemoveVietnameseTones(kw.ToLower()).Trim();



                if (string.IsNullOrWhiteSpace(kwNoTone)) continue;







                Product? bestMatch = null;



                int bestScore = 0;







                foreach (var p in activeProducts)



                {



                    if (usedProductIds.Contains(p.Id)) continue;







                    string pNameNoTone = RemoveVietnameseTones(p.ProductName?.ToLower() ?? "");



                    string pCatNoTone = RemoveVietnameseTones(p.Category?.ToLower() ?? "");







                    // Nếu từ khóa là nguyên liệu món ăn (không hỏi về chảo, nồi, đồ dùng) -> Bỏ qua đồ gia dụng



                    bool isHousewareKw = kwNoTone.Contains("chao") || kwNoTone.Contains("noi") || kwNoTone.Contains("bep") || kwNoTone.Contains("than");



                    bool isHousewareProd = pCatNoTone.Contains("gia dung") || pCatNoTone.Contains("do dung");



                    if (!isHousewareKw && isHousewareProd) continue;







                    int score = 0;



                    // 1. Khớp chính xác cụm từ trong tên sản phẩm



                    if (pNameNoTone.Contains(kwNoTone))



                    {



                        score = 100 + (pNameNoTone.Length == kwNoTone.Length ? 50 : 0);



                    }



                    else



                    {



                        // 2. Khớp theo từng từ đơn trong Tên sản phẩm với word boundary



                        var tokens = kwNoTone.Split(' ', StringSplitOptions.RemoveEmptyEntries);



                        int matchedInName = 0;



                        foreach (var t in tokens)



                        {



                            if (t.Length > 1 && Regex.IsMatch(pNameNoTone, $@"\b{Regex.Escape(t)}\b"))



                            {



                                matchedInName++;



                            }



                        }







                        if (matchedInName >= Math.Min(2, tokens.Length))



                        {



                            score = matchedInName * 20;



                        }



                        else if (tokens.Length == 1 && matchedInName == 1)



                        {



                            score = 30;



                        }



                    }







                    if (score > bestScore)



                    {



                        bestScore = score;



                        bestMatch = p;



                    }



                }







                if (bestMatch != null && bestScore >= 20)



                {



                    usedProductIds.Add(bestMatch.Id);



                    comboItems.Add(new ComboItemDto



                    {



                        ProductId = bestMatch.Id,



                        ProductName = bestMatch.ProductName,



                        Price = bestMatch.Price,



                        Quantity = 1,



                        StoreId = !string.IsNullOrWhiteSpace(bestMatch.StoreId) ? bestMatch.StoreId : "store_default",



                        StoreName = !string.IsNullOrWhiteSpace(bestMatch.StoreName) ? bestMatch.StoreName : "ZoneMart Store",



                        ImageUrl = !string.IsNullOrWhiteSpace(bestMatch.ImageUrl) ? bestMatch.ImageUrl : "/images/anhxoanen.png"



                    });



                }



                else



                {



                    string capitalized = char.ToUpper(kw[0]) + kw.Substring(1);



                    if (!missingItems.Contains(capitalized))



                    {



                        missingItems.Add(capitalized);



                    }



                }



            }







            decimal totalFoodPrice = comboItems.Sum(it => it.Price * it.Quantity);







            double lat = request.Lat ?? 0;



            double lon = request.Lon ?? 0;



            string userLocation = "";







            // 1. Phân giải tọa độ GPS thực tế của người dùng sang tên địa danh thực tế (Ngõ/Đường/Phường/Quận/Thành phố)



            if (lat != 0 && lon != 0)



            {



                Console.WriteLine($"[GPS Backend]: Nhận tọa độ GPS thực tế cho Combo từ Client: Lat={lat}, Lon={lon}");



                try



                {



                    var (resolvedLoc, _, _, _, _, _) = await ResolveSafeLocationFromGpsAsync(lat, lon);



                    userLocation = SanitizeSafeLocation(resolvedLoc);



                    if (!string.IsNullOrWhiteSpace(userLocation))



                    {



                        Console.WriteLine($"[GPS Backend]: Đã phân giải vị trí nhận hàng thực tế cho Combo: {userLocation}");



                    }



                }



                catch (Exception ex)



                {



                    Console.WriteLine($"[GPS Backend]: Không thể phân giải GPS combo: {ex.Message}");



                }



            }







            // 2. Nếu GPS chưa phân giải được hoặc request có sẵn địa chỉ đã làm sạch



            if (string.IsNullOrWhiteSpace(userLocation) && !string.IsNullOrWhiteSpace(request.UserLocation) && request.UserLocation != "Chưa xác định cụ thể")



            {



                userLocation = SanitizeSafeLocation(request.UserLocation);



            }







            // 3. Fallback vị trí an toàn, không hardcode địa điểm cụ thể



            if (string.IsNullOrWhiteSpace(userLocation))



            {



                userLocation = "Vị trí hiện tại của bạn";



            }







            if (lat == 0 && lon == 0)



            {



                lat = 21.0368;



                lon = 105.7836;



            }







            string missingNote = missingItems.Count > 0



                ? $"Những món sau hiện chưa có trên website: {string.Join(", ", missingItems)}"



                : "";







            // 4. Phân tích số cửa hàng và tính phí vận chuyển theo cự ly thực tế của từng cửa hàng



            var distinctStores = comboItems



                .Select(it => new { Id = it.StoreId, Name = it.StoreName })



                .GroupBy(x => !string.IsNullOrWhiteSpace(x.Id) && x.Id != "store_default" ? x.Id : x.Name)



                .Select(g => g.First())



                .ToList();







            int storesCount = Math.Max(1, distinctStores.Count);



            var storeNames = distinctStores.Select(s => s.Name).Distinct().ToList();







            var activeStoresList = await GetCachedActiveStoresAsync();



            var activeStoreDict = activeStoresList?.ToDictionary(s => s.Id ?? "", s => s) ?? new Dictionary<string, Store>();







            decimal totalEconomyFee = 0;



            decimal totalExpressFee = 0;



            double totalDistKm = 0;







            for (int sIdx = 0; sIdx < storesCount; sIdx++)



            {



                var sInfo = distinctStores[sIdx];



                double distKm = 0;







                if (lat != 0 && lon != 0 && activeStoreDict.TryGetValue(sInfo.Id, out var storeEntity) &&



                    storeEntity.Location?.Coordinates != null && storeEntity.Location.Coordinates.Length >= 2 &&



                    !(storeEntity.Location.Coordinates[0] == 0 && storeEntity.Location.Coordinates[1] == 0))



                {



                    distKm = CalculateDistanceKm(lat, lon, storeEntity.Location.Coordinates[1], storeEntity.Location.Coordinates[0]);



                }







                if (distKm < 0.3 || distKm > 20.0)



                {



                    // Cự ly nội thành thực tế theo chuỗi cửa hàng shipper ghé lấy



                    distKm = Math.Round(1.5 + (sIdx * 0.9), 1);



                }







                totalDistKm += distKm;







                // Phí giao hàng từng cửa hàng (quy chuẩn ZoneMart theo khoảng cách):



                // - Cự ly <= 1.5 km: 5.000 ₫ (Tiết kiệm), 8.000 ₫ (Hỏa tốc)



                // - Cự ly 1.5 - 3.0 km: 8.000 ₫ (Tiết kiệm), 11.000 ₫ (Hỏa tốc)



                // - Cự ly > 3.0 km: 12.000 ₫ (Tiết kiệm), 15.000 ₫ (Hỏa tốc)



                decimal storeEconomyFee = 5000;



                if (distKm > 3.0) storeEconomyFee = 12000;



                else if (distKm > 1.5) storeEconomyFee = 8000;







                decimal storeExpressFee = storeEconomyFee + 3000;







                totalEconomyFee += storeEconomyFee;



                totalExpressFee += storeExpressFee;



            }







            // 5. Kiểm tra điều kiện bắt buộc thanh toán QR:



            // Từ 2 quán trở lên HOẶC đơn hàng trên 300k



            bool requireQr = (storesCount >= 2) || (totalFoodPrice >= 300000m);



            string qrReason = "";



            if (storesCount >= 2 && totalFoodPrice >= 300000m)



            {



                qrReason = $"Đơn hàng gồm các món từ {storesCount} cửa hàng khác nhau và giá trị từ 300.000 ₫. Để shipper gom hàng và các quán chuẩn bị món đầy đủ nhất, ZoneMart yêu cầu thanh toán chuyển khoản qua VietQR ạ.";



            }



            else if (storesCount >= 2)



            {



                qrReason = $"Đơn hàng gồm sản phẩm từ {storesCount} cửa hàng khác nhau. Để shipper gom đơn từ các quán thuận tiện nhất, ZoneMart yêu cầu thanh toán chuyển khoản qua VietQR ạ.";



            }



            else if (totalFoodPrice >= 300000m)



            {



                qrReason = $"Đơn hàng có giá trị cao (từ 300.000 ₫). ZoneMart yêu cầu thanh toán chuyển khoản qua VietQR để bảo đảm quyền lợi và đơn hàng được xử lý ngay lập tức ạ.";



            }







            var shippingOptions = new List<ComboShippingOptionDto>



            {



                new ComboShippingOptionDto { Id = "express", Name = $"Ship Hỏa Tốc (15 - 25 phút - {storesCount} quán)", Fee = totalExpressFee, IsDefault = true },



                new ComboShippingOptionDto { Id = "economy", Name = $"Ship Tiết Kiệm (30 - 45 phút - {storesCount} quán)", Fee = totalEconomyFee, IsDefault = false }



            };







            var paymentOptions = new List<ComboPaymentOptionDto>();



            if (!requireQr)



            {



                paymentOptions.Add(new ComboPaymentOptionDto { Id = "cod", Name = "Tiền mặt khi nhận hàng (COD)", IsDefault = true });



                paymentOptions.Add(new ComboPaymentOptionDto { Id = "qr", Name = "Chuyển khoản QR (VietQR)", IsDefault = false });



            }



            else



            {



                paymentOptions.Add(new ComboPaymentOptionDto { Id = "qr", Name = "Chuyển khoản QR (VietQR) [Bắt buộc]", IsDefault = true });



            }







            var comboData = new ComboDataDto



            {



                ComboName = comboName,



                ReplyText = string.IsNullOrWhiteSpace(replyIntro) ? $"Đã gom đủ các món có sẵn cho {comboName}." : replyIntro,



                Items = comboItems,



                MissingItems = missingItems,



                MissingNote = missingNote,



                TotalFoodPrice = totalFoodPrice,



                UserLocation = userLocation,



                Lat = Math.Round(lat, 4),



                Lon = Math.Round(lon, 4),



                StoresCount = storesCount,



                StoreNames = storeNames,



                TotalDistanceKm = Math.Round(totalDistKm, 1),



                ExpressFee = totalExpressFee,



                EconomyFee = totalEconomyFee,



                RequireQr = requireQr,



                QrRequirementReason = qrReason,



                ShippingOptions = shippingOptions,



                PaymentOptions = paymentOptions



            };







            var sbReply = new StringBuilder();



            sbReply.AppendLine($"<i class=\"bi bi-collection-fill text-primary\"></i> Mình đã tìm kiếm và tổng hợp đầy đủ các nguyên liệu cho **{comboName}** từ các gian hàng ZoneMart cho bạn rồi nhé!");



            sbReply.AppendLine();



            sbReply.AppendLine($"Tổng cộng có **{comboItems.Count} món** (từ **{storesCount} cửa hàng**). Tiền món ăn: **{totalFoodPrice:N0} ₫**.");



            sbReply.AppendLine($"Phí ship tính theo quãng đường gom hàng ({storesCount} quán, cự ly ~{totalDistKm:N1} km): Tiết kiệm **{totalEconomyFee:N0} ₫**, Hỏa tốc **{totalExpressFee:N0} ₫**.");



            if (!string.IsNullOrWhiteSpace(missingNote))



            {



                sbReply.AppendLine($"<div class=\"combo-missing-note-inline\"><i class=\"bi bi-info-circle\"></i> {missingNote}</div>");



            }



            if (requireQr)



            {



                sbReply.AppendLine($"<div class=\"combo-qr-note-inline\"><i class=\"bi bi-shield-lock-fill text-warning me-1\"></i> {qrReason}</div>");



            }



            sbReply.AppendLine("Bạn có thể kiểm tra chi tiết phí ship theo khoảng cách, chọn phương thức thanh toán và bấm nút **'Đặt hàng'** ở bên dưới nhé!");







            return new



            {



                success = true,



                reply = sbReply.ToString(),



                provider = "ZoneMart AI Combo Shopper",



                actionIntent = "SHOW_COMBO_CARD",



                comboData = comboData,



                products = comboItems.Select(it => new



                {



                    id = it.ProductId,



                    name = it.ProductName,



                    price = it.Price,



                    image = it.ImageUrl,



                    storeName = it.StoreName,



                    storeId = it.StoreId



                }).ToList(),



                stores = new List<object>()



            };



        }







        private async Task<IActionResult?> TryProcessSmartCartOperationsAsync(OrderStateDto state, string cleanMsgNoTone, string userMsg)



        {



            state.CartItems ??= new List<OrderItemDto>();







            // Chuẩn hóa và bóc tách các phân đoạn theo liên từ: 'thêm', 'và', 'cho', dấu phẩy (,), chấm phẩy (;), '+', 'hoặc', 'với'



            string normalizedCmd = cleanMsgNoTone;



            // 1. Tách các dấu phân cách: phẩy, chấm phẩy, cộng, xuống dòng



            normalizedCmd = Regex.Replace(normalizedCmd, @"\s*[,;+\n]\s*", "|");



            // 2. Tách theo các liên từ: 'va', 'hoac', 'voi'



            normalizedCmd = Regex.Replace(normalizedCmd, @"\s+(?:va|hoac|voi)\s+", "|", RegexOptions.IgnoreCase);



            // 3. Tách theo 'them' hoặc 'cho' khi đứng giữa 2 món (phía trước có chữ/số, phía sau có số lượng hoặc tên món mới)



            normalizedCmd = Regex.Replace(normalizedCmd, @"(?<=[a-z0-9])\s+(?:cho\s+them|them|cho)\s+(?=\d+|[a-z])", "|", RegexOptions.IgnoreCase);







            var rawSegments = normalizedCmd.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)



                .Where(s => !string.IsNullOrWhiteSpace(s))



                .ToList();







            if (rawSegments.Count == 0) return null;







            // Tách các phân đoạn từ câu gốc (có dấu) để nhận diện chính xác các từ có dấu như 'bỏ' vs 'bò'



            string normOriginal = userMsg;



            normOriginal = Regex.Replace(normOriginal, @"\s*[,;+\n]\s*", "|");



            normOriginal = Regex.Replace(normOriginal, @"\s+(?:và|va|hoặc|hoac|với|voi)\s+", "|", RegexOptions.IgnoreCase);



            normOriginal = Regex.Replace(normOriginal, @"(?<=[a-zA-Z0-9àáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđÀÁẢÃẠĂẰẮẲẴẶÂẦẤẨẪẬÈÉẺẼẸÊỀẾỂỄỆÌÍỈĨỊÒÓỎÕỌÔỒỐỔỖỘƠỜỚỞỠỢÙÚỦŨỤƯỪỨỬỮỰỲÝỶỸỴĐ])\s+(?:cho\s+thêm|cho\s+them|thêm|them|cho)\s+(?=\d+|[a-zA-ZàáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđÀÁẢÃẠĂẰẮẲẴẶÂẦẤẨẪẬÈÉẺẼẸÊỀẾỂỄỆÌÍỈĨỊÒÓỎÕỌÔỒỐỔỖỘƠỜỚỞỠỢÙÚỦŨỤƯỪỨỬỮỰỲÝỶỸỴĐ])", "|", RegexOptions.IgnoreCase);







            var origSegments = normOriginal.Split('|', StringSplitOptions.RemoveEmptyEntries | StringSplitOptions.TrimEntries)



                .Where(s => !string.IsNullOrWhiteSpace(s))



                .ToList();







            string lastAction = "ADD";



            var changes = new List<string>();







            for (int i = 0; i < rawSegments.Count; i++)



            {



                string seg = rawSegments[i].Trim();



                string origSeg = (i < origSegments.Count) ? origSegments[i].Trim() : seg;



                string origSegLower = origSeg.ToLower();







                // Lấy số lượng q và kiểm tra xem người dùng có chỉ định số lượng cụ thể không



                int q = 1;



                bool hasExplicitQuantity = false;



                var qMatch = Regex.Match(seg, @"\b(\d+)\b");



                if (qMatch.Success && int.TryParse(qMatch.Value, out int pq) && pq > 0)



                {



                    q = pq;



                    hasExplicitQuantity = true;



                }



                else



                {



                    if (Regex.IsMatch(seg, @"\b(mot|môt|một)\b", RegexOptions.IgnoreCase)) { q = 1; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(hai)\b", RegexOptions.IgnoreCase)) { q = 2; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(ba)\b", RegexOptions.IgnoreCase)) { q = 3; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(bon|bốn)\b", RegexOptions.IgnoreCase)) { q = 4; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(nam|năm)\b", RegexOptions.IgnoreCase)) { q = 5; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(sau|sáu)\b", RegexOptions.IgnoreCase)) { q = 6; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(bay|bảy)\b", RegexOptions.IgnoreCase)) { q = 7; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(tam|tám)\b", RegexOptions.IgnoreCase)) { q = 8; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(chin|chín)\b", RegexOptions.IgnoreCase)) { q = 9; hasExplicitQuantity = true; }



                    else if (Regex.IsMatch(seg, @"\b(muoi|mười)\b", RegexOptions.IgnoreCase)) { q = 10; hasExplicitQuantity = true; }



                }







                string action = "";







                // 1. Kiểm tra DELETE (xóa, xóa bỏ, loại bỏ, hủy, remove, delete, hoặc lệnh 'bỏ hết'/'xóa hết')



                if (Regex.IsMatch(seg, @"\b(xoa|xoa\s*bo|loai\s*bo|remove|delete|huy)\b") ||



                    Regex.IsMatch(seg, @"\b(xoa\s*het|bo\s*het|huy\s*het)\b") ||



                    seg == "xoa tat ca" || seg == "bo tat ca")



                {



                    action = "DELETE";



                }



                // 2. Người dùng bảo "bỏ [món]" KHÔNG KÈM SỐ LƯỢNG -> XÓA LUÔN KHỎI GIỎ HÀNG



                else if ((origSegLower.Contains("bỏ") || Regex.IsMatch(seg, @"\bbo\b")) && !hasExplicitQuantity)



                {



                    bool isBeef = seg.Contains("thit bo") || seg.Contains("bo my") || seg.Contains("bo uc") ||



                                  seg.Contains("bo xao") || seg.Contains("bo kho") || seg.Contains("bo nuong") ||



                                  seg.Contains("bo luc lac") || seg.Contains("bo bit tet") || seg.Contains("bo vien");



                    if (!isBeef)



                    {



                        action = "DELETE";



                    }



                }







                // 3. Kiểm tra REDUCE (bớt, trừ, giảm, hoặc "bỏ" CÓ SỐ LƯỢNG)



                if (string.IsNullOrEmpty(action))



                {



                    if (Regex.IsMatch(seg, @"\b(bot|giam|tru)\b"))



                    {



                        action = "REDUCE";



                    }



                    else if ((origSegLower.Contains("bỏ") || Regex.IsMatch(seg, @"\bbo\b")) && hasExplicitQuantity)



                    {



                        bool isBeef = seg.Contains("thit bo") || seg.Contains("bo my") || seg.Contains("bo uc") ||



                                      seg.Contains("bo xao") || seg.Contains("bo kho") || seg.Contains("bo nuong") ||



                                      seg.Contains("bo luc lac") || seg.Contains("bo bit tet") || seg.Contains("bo vien");



                        if (!isBeef)



                        {



                            action = "REDUCE";



                        }



                    }



                }







                // 4. Kiểm tra ADD (thêm, cho, tăng, cộng, lấy, mua, đặt, nữa)



                if (string.IsNullOrEmpty(action))



                {



                    if (seg.Contains("them") || seg.Contains("cong") || seg.Contains("tang") || seg.Contains("nua") ||



                        Regex.IsMatch(seg, @"\b(cho|lay|mua|dat)\b"))



                    {



                        action = "ADD";



                    }



                }







                // 5. Kiểm tra SET (sửa thành, đổi thành, sửa số lượng)



                if (string.IsNullOrEmpty(action))



                {



                    if (seg.Contains("thanh") || seg.Contains("sua") || seg.Contains("doi"))



                    {



                        action = "SET";



                    }



                }







                // 6. Kế thừa hành động từ phân đoạn trước nếu là câu ghép không lặp từ khóa



                if (string.IsNullOrEmpty(action))



                {



                    action = !string.IsNullOrEmpty(lastAction) ? lastAction : "ADD";



                }



                else



                {



                    lastAction = action;



                }







                // Trích xuất từ khóa tên món segTerm (loại bỏ từ khóa hành động, số lượng, từ đệm, đại từ xưng hô)



                string segTerm = Regex.Replace(seg, @"\b(xoa\s*bo|loai\s*bo|xoa|bot|giam|tru|them|tang|cong|cho|lay|mua|dat|nua|thanh|doi|chinh|so|luong|mon|phan|suat|hop|cai|chiec|o|lon|chai|kg|g|to|bat|dia|khay|tui|di|dum|giup|ho|nhe|nha|oi|vao|gio|hang|toi|t|minh|em|anh|chi|ban|la|ten|\d+)\b", " ", RegexOptions.IgnoreCase).Trim();



                bool isBeefSeg = seg.Contains("thit bo") || seg.Contains("bo my") || seg.Contains("bo uc") ||



                                 seg.Contains("bo xao") || seg.Contains("bo kho") || seg.Contains("bo nuong") ||



                                 seg.Contains("bo luc lac") || seg.Contains("bo bit tet") || seg.Contains("bo vien");



                if (!isBeefSeg)



                {



                    segTerm = Regex.Replace(segTerm, @"\bbo\b", " ", RegexOptions.IgnoreCase).Trim();



                }



                // Chỉ loại bỏ từ số đếm ở đầu câu nếu có (ví dụ: 'một gà xối mỡ' -> 'gà xối mỡ')



                // TUYỆT ĐỐI KHÔNG loại bỏ 'tam' (tấm trong cơm tấm), 'nam' (nấm), 'chin' (chín)!



                segTerm = Regex.Replace(segTerm, @"^(?:mot|hai|ba|bon|sau|bay|muoi)\s+", "", RegexOptions.IgnoreCase).Trim();



                segTerm = Regex.Replace(segTerm, @"\s+", " ").Trim();







                // THỰC HIỆN HÀNH ĐỘNG



                if (action == "DELETE")



                {



                    var target = await FindBestMatchingCartItemAsync(state.CartItems, segTerm);



                    if (target != null)



                    {



                        state.CartItems.Remove(target);



                        changes.Add($"🗑️ Đã xóa món **{target.ProductName}** khỏi giỏ hàng");



                    }



                    else



                    {



                        changes.Add($"⚠️ Không tìm thấy món '{(string.IsNullOrWhiteSpace(segTerm) ? "này" : segTerm)}' trong giỏ hàng để xóa");



                    }



                }



                else if (action == "REDUCE")



                {



                    var target = await FindBestMatchingCartItemAsync(state.CartItems, segTerm);



                    if (target != null)



                    {



                        target.Quantity -= q;



                        if (target.Quantity <= 0)



                        {



                            state.CartItems.Remove(target);



                            changes.Add($"🗑️ Đã bớt hết món **{target.ProductName}** khỏi giỏ hàng");



                        }



                        else



                        {



                            changes.Add($"➖ Giảm món **{target.ProductName}** đi -{q} (còn lại: **{target.Quantity}**)");



                        }



                    }



                    else



                    {



                        changes.Add($"⚠️ Không tìm thấy món '{(string.IsNullOrWhiteSpace(segTerm) ? "này" : segTerm)}' trong giỏ hàng để bớt");



                    }



                }



                else if (action == "ADD")



                {



                    // Nếu từ khóa chỉ là từ ngữ chung chung chỉ đồ/hàng/món (VD: 'đồ', 'hàng', 'món', 'đồ ăn')



                    // hoặc là danh mục chung chung không có số lượng (VD: 'cơm', 'phở', 'bánh mì', 'bún')



                    // CẤM TUYỆT ĐỐI việc tự ý nhặt bừa các món ngẫu nhiên vào giỏ hàng!



                    if (IsGenericItemTerm(segTerm) || (!hasExplicitQuantity && IsGenericFoodCategoryTerm(segTerm)))



                    {



                        continue;



                    }







                    // 1. Kiểm tra xem món đã có trong giỏ hàng chưa



                    var existingInCart = await FindBestMatchingCartItemAsync(state.CartItems, segTerm);



                    if (existingInCart != null)



                    {



                        existingInCart.Quantity += q;



                        changes.Add($"➕ Tăng món **{existingInCart.ProductName}** thêm +{q} (hiện có: **{existingInCart.Quantity}**)");



                    }



                    else



                    {



                        // 2. Chưa có trong giỏ hàng: Truy xuất Database theo thời gian thực để thêm 1 dòng mới



                        if (!string.IsNullOrWhiteSpace(segTerm))



                        {



                            var foundProds = await SearchProductsInDatabaseAsync(segTerm);



                            if (foundProds != null && foundProds.Count > 0)



                            {



                                var matched = foundProds.First();



                                var inCartById = state.CartItems.FirstOrDefault(it => it.ProductId == matched.Id ||



                                    RemoveVietnameseTones(it.ProductName.ToLower()) == RemoveVietnameseTones((matched.ProductName ?? "").ToLower()));







                                if (inCartById != null)



                                {



                                    inCartById.Quantity += q;



                                    changes.Add($"➕ Tăng món **{inCartById.ProductName}** thêm +{q} (hiện có: **{inCartById.Quantity}**)");



                                }



                                else



                                {



                                    state.CartItems.Add(new OrderItemDto



                                    {



                                        ProductId = matched.Id ?? "",



                                        ProductName = matched.ProductName ?? "",



                                        Price = matched.Price,



                                        Quantity = q,



                                        StoreId = matched.StoreId ?? "store_default",



                                        StoreName = matched.StoreName ?? "ZoneMart Store",



                                        ImageUrl = !string.IsNullOrWhiteSpace(matched.ImageUrl) ? matched.ImageUrl : "/images/anhxoanen.png"



                                    });



                                    changes.Add($"🛒 Đã thêm mới **{q}x {matched.ProductName}** ({matched.Price:N0}đ/SP - Gian hàng: *{matched.StoreName ?? "ZoneMart Store"}*)");



                                }



                            }



                            else



                            {



                                changes.Add($"⚠️ Không tìm thấy món '{segTerm}' trên sàn ZoneMart");



                            }



                        }



                    }



                }



                else if (action == "SET")



                {



                    var target = await FindBestMatchingCartItemAsync(state.CartItems, segTerm);



                    if (target != null)



                    {



                        target.Quantity = q;



                        changes.Add($"✏️ Sửa món **{target.ProductName}** thành số lượng: **{q}**");



                    }



                    else



                    {



                        changes.Add($"⚠️ Không tìm thấy món '{(string.IsNullOrWhiteSpace(segTerm) ? "này" : segTerm)}' trong giỏ hàng để sửa");



                    }



                }



            }







            if (changes.Count == 0) return null;







            if (state.CartItems.Count == 0)



            {



                state.Step = "AWAITING_ITEM_NAME";



                state.PendingItem = null;



                return Ok(new



                {



                    success = true,



                    reply = $"Dạ mình đã cập nhật giỏ hàng theo yêu cầu: 🛒✨\n{string.Join("\n", changes)}\n\n🛒 **Giỏ hàng hiện tại đang trống!** Bạn có muốn chọn thêm sản phẩm nào khác không ạ? Hãy nhắn tên món bạn muốn đặt nhé! (Ví dụ: Cơm gà, Bánh mì chảo, Sữa tươi, Trái cây...)",



                    provider = "ZoneMart AI Assistant",



                    orderState = state



                });



            }







            state.Step = "ASK_ADD_MORE";



            state.PendingItem = null;



            decimal total = state.CartItems.Sum(it => it.Price * it.Quantity);



            string itemsSummary = string.Join("\n", state.CartItems.Select((it, idx) => $"  {idx + 1}️⃣ {it.Quantity}x **{it.ProductName}** ({it.Price:N0}đ/SP) = {it.Price * it.Quantity:N0}đ"));







            return Ok(new



            {



                success = true,



                reply = $"Dạ tuyệt vời! Mình đã ghi nhận vào danh sách đặt hàng: 🛒✨\n{string.Join("\n", changes)}\n\n📋 **GIỎ HÀNG HIỆN TẠI ({state.CartItems.Count} món):**\n{itemsSummary}\n\n👉 **Tổng cộng: {total:N0} ₫**\n\n**Bạn có muốn đặt thêm đồ gì nữa không ạ?** (Bấm nút 'Có' hoặc 'Không' bên dưới nhé!)",



                provider = "ZoneMart AI Assistant",



                actionIntent = "SHOW_YES_NO_ADD_MORE_BUTTONS",



                orderState = state



            });



        }







        private async Task<string> FetchRealtimeMarketDataAsync(string userMsg, string cleanMsgNoTone)



        {



            var sb = new StringBuilder();







            try



            {



                var allProducts = await GetCachedActiveProductsAsync();



                var allStores = await GetCachedActiveStoresAsync();







                // NẠP THỐNG KÊ REALTIME CHÍNH XÁC TỪ DATABASE MONGODB ATLAS



                sb.AppendLine("📊 THỐNG KÊ DỮ LIỆU REALTIME SÀN ZONEMART TỪ DATABASE MONGODB ATLAS:");



                sb.AppendLine($"  + Tổng số cửa hàng đang hoạt động: {allStores.Count} quán.");



                if (allStores.Count > 0)



                {



                    sb.AppendLine($"  + Danh sách chi tiết quán & địa chỉ: " + string.Join("; ", allStores.Select(s => $"'{s.StoreName}' (Địa chỉ: {s.Address ?? "ZoneMart Area"}, Ngành hàng: {s.Category ?? "Thực phẩm"})")));



                }



                sb.AppendLine($"  + Tổng số sản phẩm/món ăn có sẵn: {allProducts.Count} sản phẩm.\n");







                // 1. NHẬN DIỆN THỜI TIẾT (Nắng nóng / Giải nhiệt vs Trời lạnh / Trời mưa)



                bool isColdWeather = IsColdWeatherIntent(cleanMsgNoTone);



                bool isHotWeather = IsHotWeatherIntent(cleanMsgNoTone);







                if (isHotWeather)



                {



                    sb.AppendLine("☀️ BỐI CẢNH THỜI TIẾT NẮNG NÓNG: Khách hàng cần tư vấn các món ăn / đồ uống tươi mát GIẢI NHIỆT (như Dâu tây tươi Đà Lạt thanh mát, Sữa tươi tiệt trùng ướp lạnh, Trái cây, Cà chua bi, Xà lách, Sữa đặc pha sinh tố hoa quả dầm đá...). TUYỆT ĐỐI KHÔNG GỢI Ý MÓN NÓNG NHƯ BÁNH MÌ CHẢO, PHỞ HAY CƠM GÀ!");



                    sb.AppendLine("CÁC MÓN GIẢI NHIỆT CÓ SẴN THỰC TẾ TRONG DATABASE ZONEMART:");







                    var coldItems = allProducts.Where(IsProductCooling).Take(6).ToList();



                    if (coldItems.Count == 0) coldItems = allProducts.Take(5).ToList();







                    foreach (var p in coldItems)



                    {



                        sb.AppendLine($"  + Cửa hàng: [{p.StoreName ?? "ZoneMart Store"}] có món giải nhiệt mát lạnh: [{p.ProductName}] - Giá: {p.Price:N0}đ");



                    }



                }



                else if (isColdWeather)



                {



                    sb.AppendLine("❄️ BỐI CẢNH THỜI TIẾT SE LẠNH / TRỜI MƯA: Khách hàng cần tư vấn các món ăn ẤM NÓNG, bốc khói nghi ngút, ấm bụng (như Phở Bò Tái Nạm nóng hổi đậm đà, Combo Bánh Mì Chảo xèo xèo nóng hổi kèm pate, Cơm Gà xối mỡ da giòn nóng hổi, Thịt bò Mỹ nhúng lẩu nóng). TUYỆT ĐỐI KHÔNG GỢI Ý ĐỒ LẠNH!");



                    sb.AppendLine("CÁC MÓN ẤM NÓNG CÓ SẴN THỰC TẾ TRONG DATABASE ZONEMART:");







                    var warmItems = allProducts.Where(IsProductWarming).Take(6).ToList();



                    if (warmItems.Count == 0) warmItems = allProducts.Take(5).ToList();







                    foreach (var p in warmItems)



                    {



                        sb.AppendLine($"  + Cửa hàng: [{p.StoreName ?? "ZoneMart Store"}] có món nóng hổi ấm bụng: [{p.ProductName}] - Giá: {p.Price:N0}đ");



                    }



                }







                // 2. NHẬN DIỆN VỊ TRÍ VÀ BÁN KÍNH 5KM (Trần Duy Hưng, Cầu Giấy, Mai Dịch, Địa chỉ các quán...)



                bool isLocationQuery = cleanMsgNoTone.Contains("tran duy hung") || cleanMsgNoTone.Contains("cau giay") ||



                                       cleanMsgNoTone.Contains("mai dich") || cleanMsgNoTone.Contains("ban kinh") ||



                                       cleanMsgNoTone.Contains("5km") || cleanMsgNoTone.Contains("3km") ||



                                       cleanMsgNoTone.Contains("gan day") || cleanMsgNoTone.Contains("gan toi") ||



                                       cleanMsgNoTone.Contains("tim quan") || cleanMsgNoTone.Contains("dia chi") ||



                                       cleanMsgNoTone.Contains("cac quan") || cleanMsgNoTone.Contains("co trong quan") ||



                                       cleanMsgNoTone.Contains("co trong san");







                if (isLocationQuery)



                {



                    string areaName = "Cầu Giấy / Trần Duy Hưng";



                    if (cleanMsgNoTone.Contains("tran duy hung")) areaName = "Trần Duy Hưng";



                    else if (cleanMsgNoTone.Contains("mai dich")) areaName = "Mai Dịch, Cầu Giấy";



                    else if (cleanMsgNoTone.Contains("cau giay")) areaName = "Cầu Giấy";







                    sb.AppendLine($"\n📍 BỐI CẢNH VỊ TRÍ TÌM QUÁN: Khách cần tìm quán gần khu vực '{areaName}' bán kính 3km - 5km.");



                    sb.AppendLine("DANH SÁCH CỬA HÀNG CÓ THỰC TẾ TRONG DATABASE ĐANG MỞ CỬA GẦN ĐÂY:");







                    foreach (var s in allStores.Take(4))



                    {



                        sb.AppendLine($"  + Quán: [{s.StoreName}] - Địa chỉ: {s.Address} (Khoảng cách: ~0.8km - 2.5km, Giao nhanh: 12-18 phút) - Ngành hàng: {s.Category}");



                        var storeProds = allProducts.Where(p => p.StoreId == s.Id || p.StoreName == s.StoreName).Take(2).ToList();



                        foreach (var sp in storeProds)



                        {



                            sb.AppendLine($"     └ Món ngon nổi bật tại quán: [{sp.ProductName}] - Giá: {sp.Price:N0}đ");



                        }



                    }



                }







                // 3. TÌM KIẾM THEO TỪ KHÓA SẢN PHẨM KHỚP TRONG DATABASE (nếu không phải câu hỏi thời tiết)



                if (!isHotWeather && !isColdWeather)



                {



                    var matchedProducts = await SearchProductsInDatabaseAsync(cleanMsgNoTone);



                    if (matchedProducts.Count > 0)



                    {



                        sb.AppendLine($"\n🎯 CÁC SẢN PHẨM KHỚP TỪ KHÓA TÌM KIẾM '{userMsg}':");



                        foreach (var p in matchedProducts.Take(5))



                        {



                            sb.AppendLine($"  + Cửa hàng: [{p.StoreName ?? "ZoneMart Store"}] đang bán món: [{p.ProductName}] - Giá: {p.Price:N0}đ");



                        }



                    }



                    else if (!isLocationQuery)



                    {



                        bool isAskingForRecommendation = cleanMsgNoTone.Contains("goi y") || cleanMsgNoTone.Contains("tham khao") || cleanMsgNoTone.Contains("an gi") || cleanMsgNoTone.Contains("mon ngon") || cleanMsgNoTone.Contains("top mon") || cleanMsgNoTone.Contains("do an vat");



                        if (isAskingForRecommendation)



                        {



                            sb.AppendLine("\n📦 KHÁCH HỎI GỢI Ý THAM KHẢO, DƯỚI ĐÂY LÀ SẢN PHẨM THỰC TẾ TRÊN SÀN:");



                            foreach (var p in allProducts.Take(5))



                            {



                                sb.AppendLine($"  + Cửa hàng: [{p.StoreName ?? "ZoneMart Store"}] bán món: [{p.ProductName}] - Giá: {p.Price:N0}đ");



                            }



                        }



                        else



                        {



                            sb.AppendLine($"\n(Lưu ý: Không tìm thấy sản phẩm khớp chính xác từ khóa '{userMsg}'. Nếu người dùng trò chuyện đời sống/thắc mắc số liệu thì dùng dữ liệu thống kê ở trên để trả lời nhé).");



                        }



                    }



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"⚠️ [MongoDB Data Fetch Error] {ex.Message}");



            }







            return sb.ToString();



        }







        private async Task<List<object>> ExtractProductCardsAsync(string userMsg, string cleanMsgNoTone)



        {



            var cards = new List<object>();







            string[] excludeIntents = new[]



            {



                "dang ky", "tai khoan", "seller", "shipper", "mo shop", "tai xe", "dang nhap",



                "khach hang", "nguoi mua", "mo gian hang", "chay xe", "nguoi ban", "ho tro", "tro giup",



                "tu van duoc gi", "lam duoc gi", "chuc nang", "tinh nang", "giup duoc gi", "giup duoc nhung gi",



                "giup gi", "co the giup", "ho tro gi",



                "20km", "15km", "30km", "cach nha", "quang duong", "khoang cach", "giao xa", "ban kinh giao"



            };







            if (excludeIntents.Any(kw => cleanMsgNoTone.Contains(kw)))



            {



                return cards;



            }







            // CHỈ TRẢ VỀ THẺ SẢN PHẨM KHI NGƯỜI DÙNG CÓ Ý ĐỊNH MUA SẮM / HỎI MÓN ĂN / HỎI GỢI Ý / HỎI THỰC PHẨM



            bool isFoodOrProductIntent = cleanMsgNoTone.Contains("an gi") || cleanMsgNoTone.Contains("mon") ||



                                          cleanMsgNoTone.Contains("goi y") || cleanMsgNoTone.Contains("tham khao") ||



                                          cleanMsgNoTone.Contains("do an") || cleanMsgNoTone.Contains("thuc pham") ||



                                          cleanMsgNoTone.Contains("trai cay") || cleanMsgNoTone.Contains("rau") ||



                                          cleanMsgNoTone.Contains("thit") || cleanMsgNoTone.Contains("gao") ||



                                          cleanMsgNoTone.Contains("banh") || cleanMsgNoTone.Contains("pho") ||



                                          cleanMsgNoTone.Contains("bun") || cleanMsgNoTone.Contains("lau") ||



                                          cleanMsgNoTone.Contains("nuoc") || cleanMsgNoTone.Contains("kem") ||



                                          cleanMsgNoTone.Contains("che") || cleanMsgNoTone.Contains("mua") ||



                                          cleanMsgNoTone.Contains("co ban") || cleanMsgNoTone.Contains("ban khong") || cleanMsgNoTone.Contains("ban hang") ||



                                          (cleanMsgNoTone.Contains("gia") && !cleanMsgNoTone.Contains("tham gia")) ||



                                          cleanMsgNoTone.Contains("tim quan") || cleanMsgNoTone.Contains("giai nhiet") ||



                                          cleanMsgNoTone.Contains("nong hoi") ||



                                          (cleanMsgNoTone.Contains("nong") && cleanMsgNoTone.Contains("an")) ||



                                          (cleanMsgNoTone.Contains("lanh") && cleanMsgNoTone.Contains("an"));







            if (!isFoodOrProductIntent)



            {



                // Câu hỏi đời sống, ngoài lề, chuyện phiếm -> KHÔNG hiển thị thẻ sản phẩm bên dưới!



                return cards;



            }







            try



            {



                if (IsHotWeatherIntent(cleanMsgNoTone))



                {



                    var allProds = await GetCachedActiveProductsAsync();







                    var coldItems = allProds.Where(IsProductCooling).Take(4).ToList();



                    if (coldItems.Count == 0) coldItems = allProds.Take(4).ToList();







                    foreach (var p in coldItems)



                    {



                        cards.Add(new



                        {



                            id = p.Id,



                            name = p.ProductName,



                            price = p.Price,



                            image = !string.IsNullOrEmpty(p.ImageUrl) ? p.ImageUrl : "/images/anhxoanen.png",



                            storeName = p.StoreName ?? "ZoneMart Store",



                            category = p.Category



                        });



                    }



                    return cards;



                }







                if (IsColdWeatherIntent(cleanMsgNoTone))



                {



                    var allProds = await GetCachedActiveProductsAsync();







                    var warmItems = allProds.Where(IsProductWarming).Take(4).ToList();



                    if (warmItems.Count == 0) warmItems = allProds.Take(4).ToList();







                    foreach (var p in warmItems)



                    {



                        cards.Add(new



                        {



                            id = p.Id,



                            name = p.ProductName,



                            price = p.Price,



                            image = !string.IsNullOrEmpty(p.ImageUrl) ? p.ImageUrl : "/images/anhxoanen.png",



                            storeName = p.StoreName ?? "ZoneMart Store",



                            category = p.Category



                        });



                    }



                    return cards;



                }







                var matchedProducts = await SearchProductsInDatabaseAsync(cleanMsgNoTone);







                bool isWeatherQuery = cleanMsgNoTone.Contains("nong") || cleanMsgNoTone.Contains("lanh") || cleanMsgNoTone.Contains("giai nhiet") || cleanMsgNoTone.Contains("mua") || cleanMsgNoTone.Contains("ret");



                bool isLocationQuery = cleanMsgNoTone.Contains("tran duy hung") || cleanMsgNoTone.Contains("cau giay") || cleanMsgNoTone.Contains("mai dich") || cleanMsgNoTone.Contains("ban kinh") || cleanMsgNoTone.Contains("5km") || cleanMsgNoTone.Contains("gan day") || cleanMsgNoTone.Contains("gan toi");



                bool isRecommendationQuery = cleanMsgNoTone.Contains("goi y") || cleanMsgNoTone.Contains("tham khao") || cleanMsgNoTone.Contains("an gi") || cleanMsgNoTone.Contains("mon ngon") || cleanMsgNoTone.Contains("do an vat");







                if (matchedProducts.Count == 0 && (isWeatherQuery || isLocationQuery || isRecommendationQuery))



                {



                    matchedProducts = (await GetCachedActiveProductsAsync()).Take(4).ToList();



                }







                foreach (var p in matchedProducts.Take(4))



                {



                    cards.Add(new



                    {



                        id = p.Id,



                        name = p.ProductName,



                        price = p.Price,



                        image = !string.IsNullOrEmpty(p.ImageUrl) ? p.ImageUrl : "/images/anhxoanen.png",



                        storeName = p.StoreName ?? "ZoneMart Store",



                        category = p.Category



                    });



                }



            }



            catch (Exception ex)



            {



                Console.WriteLine($"⚠️ [ExtractProductCardsAsync Error] {ex.Message}");



            }







            return cards;



        }







        private async Task<List<object>> ExtractStoreCardsAsync(string userMsg, string cleanMsgNoTone)



        {



            var cards = new List<object>();







            string[] excludeIntents = new[]



            {



                "dang ky", "tai khoan", "seller", "shipper", "mo shop", "tai xe", "dang nhap",



                "khach hang", "nguoi mua", "mo gian hang", "chay xe", "nguoi ban", "ho tro", "tro giup"



            };







            if (excludeIntents.Any(kw => cleanMsgNoTone.Contains(kw)))



            {



                return cards;



            }







            // Lấy tất cả gian hàng đang Active từ cache MongoDB Atlas



            var activeStores = await GetCachedActiveStoresAsync();







            // Nếu người dùng hỏi tìm quán ở một địa điểm / khu vực cụ thể



            bool isLocationQuery = cleanMsgNoTone.Contains("quan o") || cleanMsgNoTone.Contains("shop o") ||



                                   cleanMsgNoTone.Contains("tim quan") || cleanMsgNoTone.Contains("o khu vuc") ||



                                   cleanMsgNoTone.Contains("tai khu vuc") || cleanMsgNoTone.Contains("quan o khu") ||



                                   cleanMsgNoTone.Contains("cac quan o");







            if (isLocationQuery)



            {



                // Kiểm tra xem trong DB có gian hàng nào trùng địa điểm được hỏi không



                var matchedStoresInArea = activeStores.Where(s =>



                {



                    string storeAddrClean = RemoveVietnameseTones((s.Address ?? "").ToLower());



                    if (string.IsNullOrWhiteSpace(storeAddrClean)) return false;







                    var words = cleanMsgNoTone.Split(' ', StringSplitOptions.RemoveEmptyEntries);



                    foreach (var w in words)



                    {



                        if (w.Length >= 4 && !new[] { "quan", "shop", "hien", "tai", "muon", "khu", "vuc", "giao", "hang", "co", "khong" }.Contains(w))



                        {



                            if (storeAddrClean.Contains(w)) return true;



                        }



                    }



                    return false;



                }).ToList();







                if (matchedStoresInArea.Count == 0)



                {



                    // ĐỊA ĐIỂM KHÔNG CÓ QUÁN NÀO TRONG DATABASE -> TUYỆT ĐỐI KHÔNG HIỂN THỊ THẺ THAM KHẢO!



                    return cards;



                }



                else



                {



                    foreach (var s in matchedStoresInArea.Take(4))



                    {



                        cards.Add(new



                        {



                            id = s.Id,



                            name = s.StoreName,



                            address = s.Address,



                            avatar = "/images/seller_mascot_clean.png",



                            rating = 4.9



                        });



                    }



                    return cards;



                }



            }







            bool isAskingForStores = cleanMsgNoTone.Contains("quan hot") || cleanMsgNoTone.Contains("top quan") ||



                                   cleanMsgNoTone.Contains("best seller") || cleanMsgNoTone.Contains("tran duy hung") ||



                                   cleanMsgNoTone.Contains("cau giay") || cleanMsgNoTone.Contains("mai dich") ||



                                   cleanMsgNoTone.Contains("ban kinh") || cleanMsgNoTone.Contains("5km") ||



                                   cleanMsgNoTone.Contains("3km") || cleanMsgNoTone.Contains("gan day") ||



                                   cleanMsgNoTone.Contains("gan toi") || cleanMsgNoTone.Contains("cac quan") ||



                                   cleanMsgNoTone.Contains("co trong quan") || cleanMsgNoTone.Contains("co trong san");







            if (!isAskingForStores)



            {



                return cards;



            }







            try



            {



                foreach (var s in activeStores.Take(4))



                {



                    cards.Add(new



                    {



                        id = s.Id,



                        name = s.StoreName,



                        address = s.Address,



                        avatar = "/images/seller_mascot_clean.png",



                        rating = 4.9



                    });



                }



            }



            catch { }



            return cards;



        }







        private bool IsProfaneOrInappropriate(string userMsg, string cleanMsgNoTone)



        {



            if (string.IsNullOrWhiteSpace(userMsg)) return false;







            string rawLower = userMsg.ToLower();







            // 1. Danh sách từ có dấu / từ lóng viết tắt thô tục rõ ràng



            string[] exactProfaneList = new[]



            {



                "lồn", "cặc", "đm", "đkm", "clm", "vcl", "địt", "buồi", "đéo", "phò", "chửi",



                "fuck", "bitch", "cai l", "d.m", "d.k.m", "v.l", "c.l.m", "lồn"



            };







            foreach (var kw in exactProfaneList)



            {



                if (rawLower.Contains(kw))



                {



                    return true;



                }



            }







            // 2. Phân tách ranh giới từ (\b) cho các từ thô tục rõ ràng (không chứa từ Tiếng Việt thông dụng như 'các', 'phở', 'lon')



            string pattern = @"\b(cack|dkm|clm|vcl|vl|dit|deo)\b";



            if (Regex.IsMatch(cleanMsgNoTone, pattern, RegexOptions.IgnoreCase))



            {



                return true;



            }







            if (Regex.IsMatch(cleanMsgNoTone, @"\bbuoi\b", RegexOptions.IgnoreCase))



            {



                // Loại trừ "buổi" (buổi sáng, buổi tối, buổi trưa...) và "bưởi" (trái bưởi, chè bưởi...)



                if (!rawLower.Contains("buổi") && !rawLower.Contains("bưởi"))



                {



                    return true;



                }



            }







            return false;



        }







