        private static bool ValidateZoneMartGmail(string rawEmail, bool isHtml, out string errorMessage)



        {



            if (string.IsNullOrWhiteSpace(rawEmail))



            {



                errorMessage = isHtml



                    ? @"<i class=""bi bi-exclamation-triangle-fill me-1"" style=""color: #F59E0B;""></i> Địa chỉ Gmail không được để trống! Vui lòng nhập lại Gmail của bạn nhé!"



                    : "⚠️ Địa chỉ Gmail không được để trống! Vui lòng nhập lại Gmail của bạn nhé!";



                return false;



            }







            rawEmail = rawEmail.Trim().ToLowerInvariant();



            int atCount = rawEmail.Count(c => c == '@');



            int dotCount = rawEmail.Count(c => c == '.');







            // Quy luật đăng ký: Chỉ được phép nhập đúng 1 dấu chấm "." và đúng 1 ký tự "@". Từ 2 dấu chấm trở lên như do.binh@gmail.com là không nhận.



            if (dotCount > 1)



            {



                errorMessage = isHtml



                    ? @"<i class=""bi bi-exclamation-triangle-fill me-1"" style=""color: #F59E0B;""></i> Địa chỉ Gmail không hợp lệ! Khi đăng ký, Gmail chỉ được phép có đúng 1 dấu chấm ""."" và đúng 1 ký tự ""@"" (từ 2 dấu chấm trở lên như <code>do.binh@gmail.com</code> hệ thống sẽ không nhận). Vui lòng nhập lại Gmail có đúng 1 dấu chấm (Ví dụ: <code>binh@gmail.com</code>) nhé!"



                    : "⚠️ Địa chỉ Gmail không hợp lệ! Khi đăng ký, Gmail chỉ được phép có đúng 1 dấu chấm \".\" và đúng 1 ký tự \"@\" (từ 2 dấu chấm trở lên như `do.binh@gmail.com` hệ thống sẽ không nhận). Vui lòng nhập lại Gmail có đúng 1 dấu chấm (Ví dụ: `binh@gmail.com`) nhé!";



                return false;



            }







            if (atCount != 1 || dotCount != 1 || !Regex.IsMatch(rawEmail, @"^[a-zA-Z0-9_%+-]+@gmail\.com$"))



            {



                errorMessage = isHtml



                    ? @"<i class=""bi bi-exclamation-triangle-fill me-1"" style=""color: #F59E0B;""></i> Địa chỉ Gmail không hợp lệ! Gmail bắt buộc phải có đuôi <strong>@gmail.com</strong>, chỉ có đúng 1 ký tự ""@"" và đúng 1 dấu chấm ""."" (Ví dụ: <code>binh@gmail.com</code>, không nhận từ 2 dấu chấm trở lên như <code>do.binh@gmail.com</code>)! Vui lòng nhập lại nhé!"



                    : "⚠️ Địa chỉ Gmail không hợp lệ! Gmail bắt buộc phải có đuôi **@gmail.com**, chỉ có đúng 1 ký tự \"@\" và đúng 1 dấu chấm \".\" (Ví dụ: `binh@gmail.com`, không nhận từ 2 dấu chấm trở lên như `do.binh@gmail.com`)! Vui lòng nhập lại nhé!";



                return false;



            }







            errorMessage = "";



            return true;



        }







        private async Task<object?> TryProcessAiDirectRegistrationAsync(string userMsg, string cleanMsgNoTone, string? currentRegState, List<ChatMessageItem>? history, DirectRegDraft? incomingDraft, ChatRequest? request = null)



        {



            if (string.IsNullOrWhiteSpace(userMsg)) return null;







            // CHẶN NGAY CÁC CÂU HỎI LẤY MẬT KHẨU / TÀI KHOẢN / ADMIN



            if (IsCredentialsLeakRequest(userMsg, cleanMsgNoTone) || cleanMsgNoTone.Contains("admin"))



            {



                return null;



            }







            string activeState = currentRegState ?? "NONE";



            var draft = incomingDraft ?? new DirectRegDraft();







            // 1. NẾU ĐANG Ở CÁC BƯỚC CHỈNH SỬA VÀ BẤM/NHẮN "QUAY LẠI" HOẶC "LƯU VÀ QUAY LẠI" -> TRỞ VỀ BẢNG TỔNG KẾT HỒ SƠ



            if (activeState.StartsWith("REGISTER_SELLER_EDIT") && (cleanMsgNoTone == "quay lai" || cleanMsgNoTone == "back" || cleanMsgNoTone.Contains("quay ve bang tong ket") || cleanMsgNoTone.Contains("quay lai") || cleanMsgNoTone.Contains("luu va quay lai") || cleanMsgNoTone == "luu" || cleanMsgNoTone.Contains("luu ho so")))



            {



                return new



                {



                    success = true,



                    reply = BuildSellerReviewSummaryReply(draft),



                    provider = "ZoneMart AI Direct Registration Engine",



                    registrationState = "REGISTER_SELLER_REVIEW_SUMMARY",



                    actionIntent = "SELLER_REVIEW_SUMMARY",



                    regDraft = draft



                };



            }



            if (activeState.StartsWith("REGISTER_SHIPPER_EDIT") && (cleanMsgNoTone == "quay lai" || cleanMsgNoTone == "back" || cleanMsgNoTone.Contains("quay ve bang tong ket") || cleanMsgNoTone.Contains("quay lai") || cleanMsgNoTone.Contains("luu va quay lai") || cleanMsgNoTone == "luu" || cleanMsgNoTone.Contains("luu ho so")))



            {



                return new



                {



                    success = true,



                    reply = BuildShipperReviewSummaryReply(draft),



                    provider = "ZoneMart AI Direct Registration Engine",



                    registrationState = "REGISTER_SHIPPER_REVIEW_SUMMARY",



                    actionIntent = "SHIPPER_REVIEW_SUMMARY",



                    regDraft = draft



                };



            }







            // 1b. KIỂM TRA LỆNH "HỦY YÊU CẦU" / "HỦY ĐĂNG KÝ" (CHỈ HỦY KHI NGƯỜI DÙNG NHẮN TỪ "HỦY")



            bool isExplicitCancel = Regex.IsMatch(cleanMsgNoTone, @"\b(huy yeu cau|huy dang ky|khong muon dang ky|khong dang ky nua|khong muon lam nua|dung dang ky|huy luong|dung lai|thoat)\b") ||



                                    Regex.IsMatch(cleanMsgNoTone, @"^\s*(huy|cancel|dung|thoat)\s*$");







            if (isExplicitCancel)



            {



                return new



                {



                    success = true,



                    reply = "Dạ mình đã hủy yêu cầu đăng ký cho bạn rồi nhé! 😊 Bây giờ bạn có thể trò chuyện và đặt các câu hỏi khác cùng mình bình thường nhé!",



                    provider = "ZoneMart AI Direct Registration Engine",



                    registrationState = "NONE",



                    actionIntent = (string?)null,



                    regDraft = new DirectRegDraft()



                };



            }







            // 1b-1. XỬ LÝ KHI NGƯỜI DÙNG TẢI ẢNH (TRONG LUỒNG SELLER / SHIPPER VÀ CẢ LUỒNG NÂNG CẤP HOẶC RE-UPLOAD)

            bool isPhotoUploadMsg = (userMsg.Trim().StartsWith("[Ảnh") || userMsg.Trim().StartsWith("[Anh")) &&

                                    (userMsg.Contains("đã tải") || userMsg.Contains("thành công") || userMsg.Contains("da tai") || userMsg.Contains("thanh cong"));



            if (isPhotoUploadMsg)

            {

                // Đồng bộ toàn bộ các trường ảnh từ incomingDraft (nếu có)

                if (!string.IsNullOrWhiteSpace(incomingDraft?.PortraitImage)) draft.PortraitImage = incomingDraft.PortraitImage;

                if (!string.IsNullOrWhiteSpace(incomingDraft?.CccdFrontImage)) draft.CccdFrontImage = incomingDraft.CccdFrontImage;

                if (!string.IsNullOrWhiteSpace(incomingDraft?.CccdBackImage)) draft.CccdBackImage = incomingDraft.CccdBackImage;

                if (!string.IsNullOrWhiteSpace(incomingDraft?.DrivingLicenseImage)) draft.DrivingLicenseImage = incomingDraft.DrivingLicenseImage;

                if (!string.IsNullOrWhiteSpace(incomingDraft?.FoodSafetyImage)) draft.FoodSafetyImage = incomingDraft.FoodSafetyImage;



                string photoTitle = "giấy tờ";

                string targetExpectedStateSeller = "";

                string targetExpectedStateShipper = "";



                if (userMsg.Contains("CCCD Mặt Trước") || cleanMsgNoTone.Contains("cccd mat truoc") || activeState.Contains("CCCD_FRONT"))

                {

                    photoTitle = "CCCD Mặt Trước";

                    targetExpectedStateSeller = "REGISTER_SELLER_Q12_CCCD_FRONT";

                    targetExpectedStateShipper = "REGISTER_SHIPPER_Q7_CCCD_FRONT";

                    if (!string.IsNullOrWhiteSpace(incomingDraft?.CccdFrontImage))

                        draft.CccdFrontImage = incomingDraft.CccdFrontImage;

                }

                else if (userMsg.Contains("CCCD Mặt Sau") || cleanMsgNoTone.Contains("cccd mat sau") || activeState.Contains("CCCD_BACK"))

                {

                    photoTitle = "CCCD Mặt Sau";

                    targetExpectedStateSeller = "REGISTER_SELLER_Q13_CCCD_BACK";

                    targetExpectedStateShipper = "REGISTER_SHIPPER_Q8_CCCD_BACK";

                    if (!string.IsNullOrWhiteSpace(incomingDraft?.CccdBackImage))

                        draft.CccdBackImage = incomingDraft.CccdBackImage;

                }

                else if (userMsg.Contains("An Toàn Thực Phẩm") || cleanMsgNoTone.Contains("an toan thuc pham") || cleanMsgNoTone.Contains("attp") || activeState.Contains("FOOD_SAFETY"))

                {

                    photoTitle = "Giấy CN An Toàn Thực Phẩm";

                    targetExpectedStateSeller = "REGISTER_SELLER_Q14_FOOD_SAFETY";

                    if (!string.IsNullOrWhiteSpace(incomingDraft?.FoodSafetyImage))

                        draft.FoodSafetyImage = incomingDraft.FoodSafetyImage;

                }

                else if (userMsg.Contains("Chân Dung") || cleanMsgNoTone.Contains("chan dung") || activeState.Contains("PORTRAIT"))

                {

                    photoTitle = "Ảnh Chân Dung Tài Xế";

                    targetExpectedStateShipper = "REGISTER_SHIPPER_Q6_PORTRAIT";

                    if (!string.IsNullOrWhiteSpace(incomingDraft?.PortraitImage))

                        draft.PortraitImage = incomingDraft.PortraitImage;

