        private static string ExtractField(string input, string pattern)



        {



            var match = Regex.Match(input, pattern, RegexOptions.IgnoreCase);



            if (match.Success && match.Groups.Count >= 3)



            {



                return match.Groups[2].Value.Trim();



            }



            return string.Empty;



        }







        private static bool TryValidateZoneMartOrderCode(string input, out string formattedCode, out string? errorMessage)



        {



            formattedCode = string.Empty;



            errorMessage = null;







            if (string.IsNullOrWhiteSpace(input))



            {



                errorMessage = "⚠️ Vui lòng nhập mã đơn hàng hoặc chọn [Bỏ qua bước này (Không có mã đơn)]!";



                return false;



            }







            string trimmed = input.Trim();







            // 1. Kiểm tra dấu chấm hoặc dấu phẩy



            if (trimmed.Contains('.') || trimmed.Contains(','))



            {



                errorMessage = "⚠️ Mã đơn hàng không được chứa dấu chấm '.' hoặc dấu phẩy ','!\n" +



                               "Mã đơn chỉ nhận phần chữ **ZM**, dấu gạch ngang **-** và tối đa 6 chữ số (Ví dụ: `ZM-012345`).\n\n" +



                               "Vui lòng nhập lại mã đơn hoặc chọn **[Bỏ qua bước này (Không có mã đơn)]** nhé!";



                return false;



            }







            // 2. Kiểm tra mẫu: Bắt đầu bằng ZM (in hoa hay thường đều được), dấu gạch ngang '-', và các chữ số



            var match = Regex.Match(trimmed, @"^(?i)zm\s*-\s*([0-9]+)$");



            if (!match.Success)



            {



                errorMessage = "⚠️ Mã đơn hàng không đúng định dạng!\n" +



                               "Quy cách chuẩn mã đơn hàng ZoneMart:\n" +



                               "- Phần chữ bắt buộc là **ZM** (khách viết thường `zm` sẽ tự động chuyển thành in hoa `ZM`)\n" +



                               "- Phần gạch bắt buộc là dấu gạch ngang **-** (viết gần như `ZM-` hoặc cách ra như `ZM - ` đều được nhận)\n" +



                               "- Phần số gồm từ **1 đến 6 chữ số** (Ví dụ: `ZM-012345`, `ZM-1234`)\n\n" +



                               "Vui lòng nhập lại đúng định dạng mã đơn, hoặc bấm **[Bỏ qua bước này (Không có mã đơn)]** bên dưới nhé!";



                return false;



            }







            string digits = match.Groups[1].Value;



            if (digits.Length < 1 || digits.Length > 6)



            {



                errorMessage = $"⚠️ Số lượng chữ số không hợp lệ (Hiện tại bạn nhập {digits.Length} số)! Mã đơn chỉ nhận tối thiểu 1 số và tối đa 6 số (Ví dụ: `ZM-012345`, `ZM-99`).\n\nVui lòng nhập lại mã đơn hoặc chọn **[Bỏ qua bước này (Không có mã đơn)]** nhé!";



                return false;



            }







            formattedCode = $"ZM-{digits}";



            return true;



        }







        private static string CleanPersonName(string input)



        {



            if (string.IsNullOrWhiteSpace(input)) return string.Empty;



            string cleaned = input.Trim();







            // 1. Trích xuất sau các cụm từ xưng hô + "là": "dạ", "tôi tên là", "tên tôi là", "tên em là", "mình tên là", "em là", "tôi là", "tên là", "là"



            var m = Regex.Match(cleaned, @"^(?:dạ\s+)?(?:(?:tôi|mình|em|anh|chị|cháu|bác)\s+)?(?:tên\s+(?:tôi|mình|em|anh|chị)\s+)?(?:tên\s+)?là\s+(.+)$", RegexOptions.IgnoreCase);



            if (m.Success && !string.IsNullOrWhiteSpace(m.Groups[1].Value))



            {



                cleaned = m.Groups[1].Value.Trim();



            }



            else



            {



                var m2 = Regex.Match(cleaned, @"^(?:dạ\s+)?(?:tôi|mình|em|anh|chị)?\s*(?:tên\s*)?[:\-]\s*(.+)$", RegexOptions.IgnoreCase);



                if (m2.Success && !string.IsNullOrWhiteSpace(m2.Groups[1].Value))



                {



                    cleaned = m2.Groups[1].Value.Trim();



                }



                else



                {



                    var m3 = Regex.Match(cleaned, @"\blà\s+([a-zA-Z\sàáảãạăằắẳẵặâầấẩẫậèéẻẽẹêềếểễệìíỉĩịòóỏõọôồốổỗộơờớởỡợùúủũụưừứửữựỳýỷỹỵđÀÁẢÃẠĂẰẮẲẴẶÂẦẤẨẪẬÈÉẺẼẸÊỀẾỂỄỆÌÍỈĨỊÒÓỎÕỌÔỒỐỔỖỘƠỜỚỞỠỢÙÚỦŨỤƯỪỨỬỮỰỲÝỶỸỴĐ]+)$", RegexOptions.IgnoreCase);



                    if (m3.Success && !string.IsNullOrWhiteSpace(m3.Groups[1].Value))



                    {



                        cleaned = m3.Groups[1].Value.Trim();



                    }



                }



            }







            // Loại bỏ dấu câu ở cuối (chấm, phẩy, than, hỏi)



            cleaned = Regex.Replace(cleaned, @"[.,!?;:]+$", "").Trim();



            return cleaned;



        }







        private static bool TryParseStoreHoursQuery(string userMsg, string cleanMsgNoTone, out TimeSpan targetTime, out string timeDisplay)



        {



            targetTime = TimeSpan.Zero;



            timeDisplay = string.Empty;







            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;







            // Phân loại: Có phải là câu hỏi về giờ mở cửa / bán hàng / cửa hàng không?



            bool hasStoreOrSellingKeyword =



                cleanMsgNoTone.Contains("mo cua") ||



                cleanMsgNoTone.Contains("mo ban") ||



                cleanMsgNoTone.Contains("dang mo") ||



                cleanMsgNoTone.Contains("co mo") ||



                cleanMsgNoTone.Contains("ban hang") ||



                cleanMsgNoTone.Contains("ai ban") ||



                cleanMsgNoTone.Contains("co ban") ||



                cleanMsgNoTone.Contains("quan nao") ||



                cleanMsgNoTone.Contains("tiem nao") ||



                cleanMsgNoTone.Contains("shop nao") ||



                cleanMsgNoTone.Contains("cua hang nao") ||



                cleanMsgNoTone.Contains("gian hang nao") ||



                cleanMsgNoTone.Contains("san pham") ||



                cleanMsgNoTone.Contains("co quan") ||



                cleanMsgNoTone.Contains("co cua hang") ||



                cleanMsgNoTone.Contains("con mo");







            // 1. Kiểm tra giờ cụ thể: 18h, 18 giờ, 18g, 18:00, 18h30, 6h chiều, 7h sáng...



            var timeMatch = Regex.Match(cleanMsgNoTone, @"\b(?:tam\s+|khoang\s+|luc\s+|vao\s+)?(\d{1,2})(?::(\d{2})|\s*(?:h|gio|g)(?:\s*(\d{1,2}))?)\b", RegexOptions.IgnoreCase);



            if (timeMatch.Success && int.TryParse(timeMatch.Groups[1].Value, out int h))



            {



                int m = 0;



                if (!string.IsNullOrEmpty(timeMatch.Groups[2].Value) && int.TryParse(timeMatch.Groups[2].Value, out int parsedM2))



                {



                    m = parsedM2;



                }



                else if (!string.IsNullOrEmpty(timeMatch.Groups[3].Value) && int.TryParse(timeMatch.Groups[3].Value, out int parsedM3))



                {



                    m = parsedM3;



                }







                // Kiểm tra chiều/tối/đêm (VD: 6h chiều, 7h tối, 11h đêm)



                if (cleanMsgNoTone.Contains("chieu") || cleanMsgNoTone.Contains("toi") || cleanMsgNoTone.Contains("dem"))



                {



                    if (h >= 1 && h <= 11) h += 12;



                }



                else if (cleanMsgNoTone.Contains("sang") || cleanMsgNoTone.Contains("trua"))



                {



                    if (h == 12 && cleanMsgNoTone.Contains("dem")) h = 0;



                }







                if (h >= 0 && h <= 24 && m >= 0 && m < 60)



                {



                    if (h == 24) h = 0;



                    targetTime = new TimeSpan(h, m, 0);



                    timeDisplay = $"{h:D2}:{m:D2}";







                    bool isPureTimeQuery = Regex.IsMatch(cleanMsgNoTone.Trim(), @"^(?:tam\s+|khoang\s+|luc\s+|vao\s+)?\d{1,2}(?::\d{2}|\s*(?:h|gio|g)(?:\s*\d{1,2})?)(?:\s*(?:chieu|toi|sang|trua|dem))?(?:\s*(?:co\s+gi|ban\s+gi|the\s+nao|a|nhi|khong|ko))?$");







                    if (hasStoreOrSellingKeyword || isPureTimeQuery)



                    {



                        return true;



                    }



                }



            }







            // 2. Kiểm tra câu hỏi theo thời gian hiện tại / bây giờ: "bây giờ có quán nào mở cửa không", "hiện tại quán nào mở", "quán nào đang mở"



            bool isNowQuery = cleanMsgNoTone.Contains("bay gio") || cleanMsgNoTone.Contains("hien tai") || cleanMsgNoTone.Contains("luc nay") || cleanMsgNoTone.Contains("dang mo");



            if (isNowQuery && hasStoreOrSellingKeyword)



            {



                var nowVn = DateTime.UtcNow.AddHours(7);



                targetTime = nowVn.TimeOfDay;



                timeDisplay = $"bây giờ ({nowVn:HH:mm})";



                return true;



            }







            return false;



        }







        private static bool IsStoreOpenAtTime(string? openHoursStr, TimeSpan targetTime)



        {



            if (string.IsNullOrWhiteSpace(openHoursStr))



            {



                openHoursStr = "07:00 - 22:00";



            }







            string s = openHoursStr.Trim();



            if (s.Contains("24/24") || s.Contains("24/7"))



            {



                return true;



            }







            var matches = Regex.Matches(s, @"(\d{1,2})(?::(\d{1,2})|\s*(?:h|giờ))?", RegexOptions.IgnoreCase);



            if (matches.Count >= 2 &&



                int.TryParse(matches[0].Groups[1].Value, out int h1) &&



                int.TryParse(matches[1].Groups[1].Value, out int h2))



            {



                int m1 = 0;



                int m2 = 0;



                if (!string.IsNullOrEmpty(matches[0].Groups[2].Value) && int.TryParse(matches[0].Groups[2].Value, out int parsedM1)) m1 = parsedM1;



                if (!string.IsNullOrEmpty(matches[1].Groups[2].Value) && int.TryParse(matches[1].Groups[2].Value, out int parsedM2)) m2 = parsedM2;







                var start = new TimeSpan(h1, m1, 0);



                var end = new TimeSpan(h2 == 24 ? 23 : h2, h2 == 24 ? 59 : m2, 0);







                if (start <= end)



                {



                    return targetTime >= start && targetTime <= end;



                }



                else



                {



                    // Mở xuyên đêm (VD: 18:00 đến 03:00 sáng hôm sau)



                    return targetTime >= start || targetTime <= end;



                }



            }







            return true; // Fallback an toàn



        }







        private static bool IsColdWeatherIntent(string cleanMsgNoTone, string userMsg = "")



        {



            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;



            string origLower = (userMsg ?? "").ToLower();







            // Chú ý: "đỡ nóng", "bớt nóng", "giảm nóng", "chống nóng" là muốn giải nhiệt (HOT weather intent), không phải món nóng!



            if (origLower.Contains("đỡ nóng") || origLower.Contains("bớt nóng") || origLower.Contains("giảm nóng") ||



                origLower.Contains("hết nóng") || origLower.Contains("chống nóng"))



            {



                return false;



            }







            return cleanMsgNoTone.Contains("se lanh") || cleanMsgNoTone.Contains("troi lanh") ||



                   cleanMsgNoTone.Contains("thoi tiet lanh") || cleanMsgNoTone.Contains("ret") ||



                   cleanMsgNoTone.Contains("mua lanh") || cleanMsgNoTone.Contains("troi mua") ||



                   cleanMsgNoTone.Contains("gio mua") || cleanMsgNoTone.Contains("am nong") ||



                   cleanMsgNoTone.Contains("am bung") || cleanMsgNoTone.Contains("suyt xoa") ||



                   cleanMsgNoTone.Contains("mua dong") || cleanMsgNoTone.Contains("ngay lanh") ||



                   cleanMsgNoTone.Contains("mon nong") || cleanMsgNoTone.Contains("an do nong") ||



                   cleanMsgNoTone.Contains("an gi am nong") || cleanMsgNoTone.Contains("an gi do nong") ||



                   origLower.Contains("đồ nóng") || origLower.Contains("món nóng") || origLower.Contains("ấm nóng") || origLower.Contains("nóng hổi") ||



                   (cleanMsgNoTone.Contains("lanh") && !cleanMsgNoTone.Contains("mat lanh") && !cleanMsgNoTone.Contains("uop lanh") && !cleanMsgNoTone.Contains("da lanh"));



        }







        private static bool IsHotWeatherIntent(string cleanMsgNoTone, string userMsg = "")



        {



            if (string.IsNullOrWhiteSpace(cleanMsgNoTone)) return false;



            if (cleanMsgNoTone.Contains("mon an") || cleanMsgNoTone.Contains("mon nong") ||
                cleanMsgNoTone.Contains("do an nong") || cleanMsgNoTone.Contains("do nong") ||
                IsCategoryBrowseIntent(cleanMsgNoTone, userMsg))
            {
                return false;
            }

            if (IsColdWeatherIntent(cleanMsgNoTone, userMsg)) return false;







            string origLower = (userMsg ?? "").ToLower();







            return cleanMsgNoTone.Contains("troi nong") || cleanMsgNoTone.Contains("thoi tiet nong") ||



                   cleanMsgNoTone.Contains("nang nong") || cleanMsgNoTone.Contains("oi buc") ||



                   cleanMsgNoTone.Contains("oi a") || cleanMsgNoTone.Contains("giai nhiet") ||



                   cleanMsgNoTone.Contains("giai khat") || cleanMsgNoTone.Contains("mat lanh") ||



                   cleanMsgNoTone.Contains("thanh nhiet") || cleanMsgNoTone.Contains("do mat") ||



                   cleanMsgNoTone.Contains("mon mat") || cleanMsgNoTone.Contains("mon lanh") ||



                   cleanMsgNoTone.Contains("giam nhiet") || cleanMsgNoTone.Contains("mua he") ||



                   cleanMsgNoTone.Contains("ngay he") || cleanMsgNoTone.Contains("ngay nong") ||



                   origLower.Contains("đỡ nóng") || origLower.Contains("bớt nóng") || origLower.Contains("giảm nóng") ||



                   (cleanMsgNoTone.Contains("nong") && !cleanMsgNoTone.Contains("nong hoi") && !cleanMsgNoTone.Contains("am nong"));



        }







        private static bool IsProductCooling(Product p)



        {



            if (p == null) return false;



            string name = RemoveVietnameseTones(p.ProductName ?? "").ToLower();



            string cat = RemoveVietnameseTones(p.Category ?? "").ToLower();



            string desc = RemoveVietnameseTones(p.Description ?? "").ToLower();







            // 1. Tuyệt đối loại trừ đồ gia dụng / phi thực phẩm



            if (cat.Contains("gia dung") || cat.Contains("do dung") ||



                name.Contains("chao chong dinh") || name.Contains("noi inox") || name.Contains("bo noi") ||



                name.Contains("nuoc rua bat") || name.Contains("tui rac") || name.Contains("khan"))



            {



                return false;



            }







            // 2. Tuyệt đối loại trừ các món ăn nóng / xào / nướng / lẩu / bốc khói / bánh mì chảo / thịt kho



            if (cat.Contains("mon an nong") || name.Contains("banh mi chao") || name.Contains("pho") ||



                name.Contains("com ga") || name.Contains("com tam") || name.Contains("banh bao") ||



                name.Contains("lau") || name.Contains("nuong") || name.Contains("chao") ||



                name.Contains("nong hoi") || name.Contains("thit bo my") || name.Contains("thit trau") ||



                name.Contains("canh cua") || name.Contains("khoai lang"))



            {



                return false;



            }







            // 3. Các sản phẩm mát lạnh / giải nhiệt / mùa hè (ưu tiên đồ uống, hoa quả mọng nước, giải khát):



            return cat.Contains("trai cay") || cat.Contains("do uong") || cat.Contains("rau cu") ||



                   name.Contains("tra tac") || name.Contains("ca phe") || name.Contains("dua xiem") ||



                   name.Contains("dau tay") || name.Contains("cam sanh") || name.Contains("xoai cat") ||



                   name.Contains("buoi da xanh") || name.Contains("ca chua") || name.Contains("ot chuong") ||



                   name.Contains("xa lach") || name.Contains("rau muong") || name.Contains("bi xanh") ||



                   name.Contains("sua tuoi") || name.Contains("sua dac") || name.Contains("kem") ||



                   name.Contains("che") || name.Contains("sinh to") || name.Contains("nuoc ep") ||



                   desc.Contains("mat lanh") || desc.Contains("giai nhiet") || desc.Contains("thanh nhiet") ||



                   desc.Contains("mong nuoc") || desc.Contains("giai khat") || desc.Contains("ngot mat");



        }







        private static bool IsProductWarming(Product p)



        {



            if (p == null) return false;



            string name = RemoveVietnameseTones(p.ProductName ?? "").ToLower();



            string cat = RemoveVietnameseTones(p.Category ?? "").ToLower();



            string desc = RemoveVietnameseTones(p.Description ?? "").ToLower();







            // 1. Tuyệt đối loại trừ đồ gia dụng / dụng cụ nhà bếp / phi thực phẩm



            if (cat.Contains("gia dung") || cat.Contains("do dung") ||



                name.Contains("chao chong dinh") || name.Contains("chao da") ||



                name.Contains("noi inox") || name.Contains("bo noi") ||



                name.Contains("nuoc rua bat") || name.Contains("tui rac") || name.Contains("khan"))



            {



                return false;



            }







            // 2. Tuyệt đối loại trừ các sản phẩm giải nhiệt / mát lạnh / hoa quả / đồ uống đá



            if (name.Contains("tra tac") || name.Contains("tra da") || name.Contains("ca phe sua da") ||



                name.Contains("dua xiem") || name.Contains("dau tay") || name.Contains("cam sanh") ||



                name.Contains("xoai cat") || name.Contains("buoi da xanh") || name.Contains("ca chua bi") ||



                name.Contains("ot chuong") || name.Contains("xa lach") || name.Contains("rau muong") ||



                name.Contains("bi xanh") || name.Contains("kem") ||



                name.Contains("che") || name.Contains("mat lanh") || name.Contains("giai nhiet") ||



                cat.Contains("trai cay") || cat.Contains("do uong"))



            {



                return false;



            }







            // 3. Các sản phẩm ấm nóng / mùa đông:



            return cat.Contains("mon an nong") ||



                   name.Contains("pho") || name.Contains("banh mi chao") || name.Contains("banh mi kep") ||



                   name.Contains("com ga") || name.Contains("com tam") || name.Contains("com nieu") ||



                   (name.Contains("chao") && !name.Contains("chao chong dinh") && !name.Contains("chao da")) ||



                   name.Contains("lau") || name.Contains("nuong") ||



                   name.Contains("bo my") || name.Contains("thit bo") || name.Contains("banh bao") ||



                   name.Contains("khoai lang") || name.Contains("thit trau") || name.Contains("canh cua") ||



                   name.Contains("canh") || name.Contains("sup") || name.Contains("nong hoi") ||



                   name.Contains("xoi mo") || name.Contains("sot") || name.Contains("ham") ||



                   desc.Contains("nong hoi") || desc.Contains("am bung") || desc.Contains("xeo xeo") ||



                   desc.Contains("nuoc dung") || desc.Contains("khoai lang");



        }







